window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[9]={"numero": 9, "titulo": "El yoga del saber soberano y el secreto soberano", "versos": [{"n": 1, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे ।", "ज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥१॥"], "iast": ["śrī-bhagavān uvāca", "idaṃ tu te guhyatamaṃ pravakṣyāmy anasūyave", "jñānaṃ vijñāna-sahitaṃ yaj jñātvā mokṣyase 'śubhāt"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Pero ahora te expondré a ti, que no buscas faltas, este saber, el más secreto: el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> junto con el <a class=\"t\" href=\"glosario.html#vijnana\" data-t=\"vijnana\">conocimiento realizado</a>; conociéndolo, quedarás libre del mal.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "idam", "sa": "इदम्", "gram": "acc. sg. n. pron.", "es": "esto, este"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, ahora"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti"}, {"iast": "guhyatamam", "sa": "गुह्यतमम्", "gram": "acc. sg. n. superl.", "es": "lo más secreto", "analisis": "guhya (secreto, lo que se oculta; de √guh, ocultar) + -tama (superlativo)"}, {"iast": "pravakṣyāmi", "sa": "प्रवक्ष्यामि", "gram": "1 sg. fut. act.", "es": "expondré", "analisis": "pra-√vac (declarar, exponer)"}, {"iast": "anasūyave", "sa": "अनसूयवे", "gram": "dat. sg. m.", "es": "al que no busca faltas", "analisis": "an- (no) + asūyu (el que censura, el que envidia; de asūyā, malevolencia, envidia)"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "acc. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "vijñāna-sahitam", "sa": "विज्ञानसहितम्", "gram": "acc. sg. n. comp.", "es": "junto con el conocimiento realizado", "ref": "vijnana", "analisis": "vijñāna (conocimiento realizado) + sahita (acompañado de)"}, {"iast": "yat", "sa": "यत्", "gram": "acc. sg. n. pron. rel.", "es": "lo cual"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "ger.", "es": "conociendo", "analisis": "√jñā (conocer)"}, {"iast": "mokṣyase", "sa": "मोक्ष्यसे", "gram": "2 sg. fut. med.", "es": "te librarás", "ref": "moksa", "analisis": "√muc (soltar, liberar)"}, {"iast": "aśubhāt", "sa": "अशुभात्", "gram": "abl. sg. n.", "es": "del mal", "analisis": "a- (no) + śubha (bueno, propicio)"}], "nota": "<p>El capítulo continúa el séptimo: la misma pareja, el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> con el <a class=\"t\" href=\"glosario.html#vijnana\" data-t=\"vijnana\">conocimiento realizado</a>, que allí se prometía (<a class=\"vref\" href=\"capitulo-07.html#v2\" data-v=\"7.2\">7.2</a>). El último cuarto del verso repite a la letra el de <a class=\"vref\" href=\"capitulo-04.html#v16\" data-v=\"4.16\">4.16</a>, <em>yaj jñātvā mokṣyase &#x27;śubhāt</em>, «sabiéndolo, quedarás libre del mal». <em>Guhyatama</em>, «lo más secreto», es un superlativo: la Gītā gradúa sus secretos, y volverá a usar el mismo en <a class=\"vref\" href=\"capitulo-15.html#v20\" data-v=\"15.20\">15.20</a> y, ya al final, el de «lo más secreto de todo» en <a class=\"vref\" href=\"capitulo-18.html#v64\" data-v=\"18.64\">18.64</a>.</p>", "interp": [{"titulo": "Una escala de secretos", "html": "<p>La Gītā habla de sus enseñanzas como de secretos de grado creciente: «secreto» (<em>guhya</em>), «más secreto» (<em>guhyatara</em>, <a class=\"vref\" href=\"capitulo-18.html#v63\" data-v=\"18.63\">18.63</a>) y «lo más secreto» (<em>guhyatama</em>, aquí, en <a class=\"vref\" href=\"capitulo-15.html#v20\" data-v=\"15.20\">15.20</a> y, con «de todo», en <a class=\"vref\" href=\"capitulo-18.html#v64\" data-v=\"18.64\">18.64</a>). No es un saber esotérico reservado a unos pocos por su contenido, sino por la disposición que pide: a quien no busca faltas puede decírsele lo que a otro no.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pero ahora te expondré a ti, que no sientes envidia, este saber, el más secreto: el conocimiento junto con el conocimiento realizado; conociéndolo, quedarás libre del mal.", "nota": "<p><em>Asūyā</em> es a la vez la malevolencia que busca defectos en lo que otro dice y la envidia ante sus méritos. La traducción principal toma el primer sentido, el que tiene en <a class=\"vref\" href=\"capitulo-03.html#v31\" data-v=\"3.31\">3.31</a>, donde <em>anasūyantaḥ</em> se tradujo «sin objetarla»: el que escucha sin buscar faltas en la enseñanza. La alternativa toma el segundo, que pone el acento en la disposición del discípulo hacia el maestro. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa sólo «libre de malevolencia» (<em>asūyā-rahita</em>); <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden como no buscar faltas en el propio Kṛṣṇa, que no deja de proclamar su grandeza.</p>"}]}, {"n": 2, "hablante": "krsna", "sa": ["राजविद्या राजगुह्यं पवित्रमिदमुत्तमम् ।", "प्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम् ॥२॥"], "iast": ["rāja-vidyā rāja-guhyaṃ pavitram idam uttamam", "pratyakṣāvagamaṃ dharmyaṃ su-sukhaṃ kartum avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Es el <a class=\"t\" href=\"glosario.html#raja-vidya\" data-t=\"raja-vidya\">saber soberano</a>, el secreto soberano, el purificador supremo; se capta por experiencia directa, es conforme al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, muy fácil de practicar e imperecedero.</span>", "palabras": [{"iast": "rāja-vidyā", "sa": "राजविद्या", "gram": "nom. sg. f. comp.", "es": "el saber soberano", "ref": "raja-vidya", "analisis": "rājan (rey) + vidyā (saber, ciencia)"}, {"iast": "rāja-guhyam", "sa": "राजगुह्यम्", "gram": "nom. sg. n. comp.", "es": "el secreto soberano", "ref": "raja-vidya", "analisis": "rājan (rey) + guhya (secreto)"}, {"iast": "pavitram", "sa": "पवित्रम्", "gram": "nom. sg. n.", "es": "purificador", "analisis": "√pū (purificar)"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "uttamam", "sa": "उत्तमम्", "gram": "nom. sg. n.", "es": "supremo, el más alto"}, {"iast": "pratyakṣāvagamam", "sa": "प्रत्यक्षावगमम्", "gram": "nom. sg. n. comp.", "es": "que se capta por experiencia directa", "analisis": "pratyakṣa (lo que está ante los ojos, la percepción directa) + avagama (comprensión)"}, {"iast": "dharmyam", "sa": "धर्म्यम्", "gram": "nom. sg. n.", "es": "conforme al dharma", "ref": "dharma"}, {"iast": "su-sukham", "sa": "सुसुखम्", "gram": "nom. sg. n.", "es": "muy fácil, muy grato", "ref": "sukha", "analisis": "su- (muy) + sukha (fácil, agradable)"}, {"iast": "kartum", "sa": "कर्तुम्", "gram": "inf.", "es": "de practicar", "analisis": "√kṛ (hacer)"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "nom. sg. n.", "es": "imperecedero", "analisis": "a- (no) + vyaya (gasto, pérdida)"}], "nota": "<p>Seis cualidades en una línea y media. <em>Pratyakṣāvagama</em>, «cuya comprensión es directa», dice que este saber no se queda en creencia: se comprueba, como se comprueba lo que se tiene delante. <em>Dharmya</em>, «conforme al dharma», que no se opone al orden recto. <em>Su-sukhaṃ kartum</em>, «muy fácil de practicar» (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>) o «muy grato», porque es lo más querido (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>), anticipa lo que dirá el capítulo: basta una hoja, una flor, un fruto o un poco de agua (<a class=\"vref\" href=\"capitulo-09.html#v26\" data-v=\"9.26\">9.26</a>). El título del capítulo, <em>Rāja-vidyā-rāja-guhya-yoga</em>, sale de este verso.</p>", "interp": [{"titulo": "El rey de los saberes", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>rāja-vidyā</em> como el rey de los saberes, por la intensidad de su luz, y <em>rāja-guhya</em> como el rey de los secretos; «rey de los saberes» leen también <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> —porque destruye toda ignorancia— y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>. Se conoce directamente, como se conoce el placer. Y a las objeciones que él mismo se plantea responde con las demás cualidades del verso: no se opone al dharma; no es difícil, sino fácil de practicar, como para el entendido distinguir piedras preciosas; y, aunque fácil, su fruto no se agota.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Fácil y supremo a la vez", "html": "<p>El verso une dos cosas que suelen ir separadas: lo más alto y lo más fácil. La Gītā ha descrito antes caminos arduos —la meditación del capítulo 6, la muerte del yogui en el 8—; aquí presenta un saber que es a la vez el más secreto y el más accesible. Es el tono de todo el capítulo, que terminará abriendo el camino a quienes la sociedad de su tiempo dejaba fuera (<a class=\"vref\" href=\"capitulo-09.html#v32\" data-v=\"9.32\">9.32</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Es el rey de los saberes, el rey de los secretos, el purificador supremo; se capta por experiencia directa, es conforme al dharma, muy fácil de practicar e imperecedero.", "nota": "<p>En <em>rāja-vidyā</em> y <em>rāja-guhya</em>, «rey» puede funcionar como un superlativo («el saber soberano», el más alto) o leerse como «el rey de los saberes», el que está por encima de todos; la alternativa hace explícita esta segunda lectura. Cabría también «el saber de los reyes», que <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> dan como segunda lectura (para Rāmānuja, los «reyes» son los de mente amplia y profunda); se oiría en ella un eco de los <a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">reyes sabios</a> que recibieron el yoga en <a class=\"vref\" href=\"capitulo-04.html#v2\" data-v=\"4.2\">4.2</a> (véase la ficha <a class=\"t\" href=\"glosario.html#raja-vidya\" data-t=\"raja-vidya\">rāja-vidyā</a>).</p>"}]}, {"n": 3, "hablante": "krsna", "sa": ["अश्रद्दधानाः पुरुषा धर्मस्यास्य परन्तप ।", "अप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि ॥३॥"], "iast": ["aśraddadhānāḥ puruṣā dharmasyāsya parantapa", "aprāpya māṃ nivartante mṛtyu-saṃsāra-vartmani"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los hombres que no tienen <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> en este <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>, no me alcanzan, y vuelven al camino del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a> y de la muerte.</span>", "palabras": [{"iast": "aśraddadhānāḥ", "sa": "अश्रद्दधानाः", "gram": "nom. pl. m. part. pres.", "es": "los que no tienen fe", "ref": "sraddha", "analisis": "a- (no) + śrad-√dhā (poner el corazón, tener fe)"}, {"iast": "puruṣāḥ", "sa": "पुरुषाः", "gram": "nom. pl. m.", "es": "los hombres"}, {"iast": "dharmasya", "sa": "धर्मस्य", "gram": "gen. sg. m.", "es": "en el dharma", "ref": "dharma"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "este"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa"}, {"iast": "aprāpya", "sa": "अप्राप्य", "gram": "ger.", "es": "sin alcanzar", "analisis": "a- (no) + pra-√āp (alcanzar)"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "nivartante", "sa": "निवर्तन्ते", "gram": "3 pl. pres. med.", "es": "vuelven", "analisis": "ni-√vṛt (volver)"}, {"iast": "mṛtyu-saṃsāra-vartmani", "sa": "मृत्युसंसारवर्त्मनि", "gram": "loc. sg. n. comp.", "es": "al camino del saṃsāra, que es muerte", "ref": "samsara", "analisis": "mṛtyu (muerte) + saṃsāra (el ciclo de los nacimientos) + vartman (camino)"}], "nota": "<p><em>Dharma</em> es aquí «esta enseñanza», el saber que se acaba de alabar, no el deber propio de cada uno. <em>Mṛtyu-saṃsāra-vartman</em> es «el camino del saṃsāra, lleno de muerte» (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>) o «del saṃsāra, que es muerte» (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>); gramaticalmente cabría también «el camino de la muerte y del saṃsāra»: en todo caso, la vuelta a nacer para volver a morir. Como en <a class=\"vref\" href=\"capitulo-04.html#v40\" data-v=\"4.40\">4.40</a>, la falta de <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> cierra la puerta a lo que el conocimiento abre.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 4, "hablante": "krsna", "sa": ["मया ततमिदं सर्वं जगदव्यक्तमूर्तिना ।", "मत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः ॥४॥"], "iast": ["mayā tatam idaṃ sarvaṃ jagad avyakta-mūrtinā", "mat-sthāni sarva-bhūtāni na cāhaṃ teṣv avasthitaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Todo este mundo está penetrado por mí, en mi forma no <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">manifiesta</a>. Todos los seres están en mí, pero yo no estoy en ellos.</span>", "palabras": [{"iast": "mayā", "sa": "मया", "gram": "instr. sg. pron.", "es": "por mí"}, {"iast": "tatam", "sa": "ततम्", "gram": "nom. sg. n. ppp.", "es": "penetrado, extendido", "analisis": "√tan (extender, tender)"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "este"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n.", "es": "todo"}, {"iast": "jagat", "sa": "जगत्", "gram": "nom. sg. n.", "es": "el mundo", "analisis": "√gam (ir): «lo que se mueve»"}, {"iast": "avyakta-mūrtinā", "sa": "अव्यक्तमूर्तिना", "gram": "instr. sg. m. comp.", "es": "en mi forma no manifiesta", "ref": "avyakta", "analisis": "avyakta (no manifiesto) + mūrti (forma, figura)"}, {"iast": "mat-sthāni", "sa": "मत्स्थानि", "gram": "nom. pl. n. comp.", "es": "están en mí", "analisis": "mad (yo) + stha (que está, que reside)"}, {"iast": "sarva-bhūtāni", "sa": "सर्वभूतानि", "gram": "nom. pl. n. comp.", "es": "todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y, pero"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. n. pron.", "es": "en ellos"}, {"iast": "avasthitaḥ", "sa": "अवस्थितः", "gram": "nom. sg. m. ppp.", "es": "estoy, resido", "analisis": "ava-√sthā (permanecer, estar asentado)"}], "nota": "<p><em>Tatam</em>, «extendido, penetrado», es la palabra de <a class=\"vref\" href=\"capitulo-02.html#v17\" data-v=\"2.17\">2.17</a> («aquello por lo que todo esto está penetrado») y volverá en <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a> y <a class=\"vref\" href=\"capitulo-18.html#v46\" data-v=\"18.46\">18.46</a>. <em>Avyakta-mūrti</em>, «de forma no manifiesta», es la forma de Kṛṣṇa que los sentidos no captan. La segunda mitad retoma <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>: «yo no estoy en ellos: ellos están en mí». El verso siguiente la llevará al extremo.</p>", "interp": [{"titulo": "Están en mí porque no son por sí", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que los seres están en el Señor porque no tienen existencia propia: sólo existen en cuanto él es su sí-mismo. Pero él no está en ellos, porque no tiene contacto con nada, y lo que no tiene contacto no puede estar contenido en otra cosa; si a los necios les parece que está en ellos, es porque es su sí-mismo. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> da la misma razón: como el espacio, no se adhiere a nada.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "De 7.12 a 9.4", "html": "<p>En <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a> la fórmula se aplicaba a los estados que nacen de las guṇas; aquí se extiende a todos los seres y al mundo entero. La imagen de fondo es la de <a class=\"vref\" href=\"capitulo-07.html#v7\" data-v=\"7.7\">7.7</a>: todo está ensartado en Kṛṣṇa como perlas en un hilo; el hilo sostiene las perlas, pero no está contenido en ninguna.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "como-el-viento-en-el-espacio"}, {"n": 5, "hablante": "krsna", "sa": ["न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम् ।", "भूतभृन्न च भूतस्थो ममात्मा भूतभावनः ॥५॥"], "iast": ["na ca mat-sthāni bhūtāni paśya me yogam aiśvaram", "bhūta-bhṛn na ca bhūta-stho mamātmā bhūta-bhāvanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y, sin embargo, los seres no están en mí: ¡mira mi <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga soberano</a>! Sostengo a los seres y no estoy en ellos; mi propio ser es el que hace existir a los seres.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y, sin embargo"}, {"iast": "mat-sthāni", "sa": "मत्स्थानि", "gram": "nom. pl. n. comp.", "es": "están en mí", "analisis": "mad (yo) + stha (que está)"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres"}, {"iast": "paśya", "sa": "पश्य", "gram": "2 sg. impv. act.", "es": "mira", "analisis": "√paś (ver)"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "yogam", "sa": "योगम्", "gram": "acc. sg. m.", "es": "yoga, poder", "ref": "yoga-maya"}, {"iast": "aiśvaram", "sa": "ऐश्वरम्", "gram": "acc. sg. m.", "es": "soberano, propio del Señor", "analisis": "īśvara (señor) + -a (derivado)"}, {"iast": "bhūta-bhṛt", "sa": "भूतभृत्", "gram": "nom. sg. m. comp.", "es": "que sostiene a los seres", "analisis": "bhūta (ser) + bhṛt (que sostiene, que lleva)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bhūta-sthaḥ", "sa": "भूतस्थः", "gram": "nom. sg. m. comp.", "es": "que está en los seres", "analisis": "bhūta (ser) + stha (que está)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "ātmā", "sa": "आत्मा", "gram": "nom. sg. m.", "es": "propio ser, yo mismo", "ref": "atman"}, {"iast": "bhūta-bhāvanaḥ", "sa": "भूतभावनः", "gram": "nom. sg. m. comp.", "es": "que hace existir a los seres", "analisis": "bhūta (ser) + bhāvana (que hace ser; caus. de √bhū)"}], "nota": "<p>El verso contradice a propósito al anterior —«están en mí» / «no están en mí»— y nombra esa paradoja <em>yogam aiśvaram</em>, el «yoga soberano»: <em>yoga</em> no es aquí una disciplina, sino un poder o un prodigio del Señor, como en <a class=\"vref\" href=\"capitulo-11.html#v8\" data-v=\"11.8\">11.8</a>, donde Kṛṣṇa dará a Arjuna ojos divinos para verlo (véase la ficha <a class=\"t\" href=\"glosario.html#yoga-maya\" data-t=\"yoga-maya\">yoga-māyā</a>). <em>Mama ātmā</em> es reflexivo: «mi propio ser», «yo mismo», no el sí-mismo de cada ser; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende aquí «mi voluntad», y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, «mi cuerpo».</p>", "interp": [{"titulo": "Tampoco están en mí", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, los seres no están en el Señor porque él no tiene contacto con nada: «sin apego, pues no se adhiere», dice la Upaniṣad. El yoga soberano es, para él, la naturaleza verdadera del sí-mismo; y es otro prodigio que, sin contacto, sostenga a los seres. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica en dos planos: los seres, imaginados en él como se atribuye al sol del cielo el temblor de su reflejo en el agua, no están en él en verdad.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sostenidos por su voluntad", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> resuelve la paradoja distinguiendo modos de estar: los seres están en Kṛṣṇa porque él los sostiene, pero no como el agua está en una vasija, que la sostiene con su cuerpo; los sostiene con su sola voluntad. Y él no está en ellos en el sentido de que su existencia no depende de ellos.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "como-el-viento-en-el-espacio"}, {"n": 6, "hablante": "krsna", "sa": ["यथाकाशस्थितो नित्यं वायुः सर्वत्रगो महान् ।", "तथा सर्वाणि भूतानि मत्स्थानीत्युपधारय ॥६॥"], "iast": ["yathākāśa-sthito nityaṃ vāyuḥ sarvatra-go mahān", "tathā sarvāṇi bhūtāni mat-sthānīty upadhāraya"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Como el gran viento, que va por todas partes, está siempre en el espacio, así todos los seres están en mí: compréndelo.</span>", "palabras": [{"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "como"}, {"iast": "ākāśa-sthitaḥ", "sa": "आकाशस्थितः", "gram": "nom. sg. m. comp.", "es": "que está en el espacio", "analisis": "ākāśa (espacio, éter) + sthita (situado)"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "ind.", "es": "siempre"}, {"iast": "vāyuḥ", "sa": "वायुः", "gram": "nom. sg. m.", "es": "el viento", "ref": "vayu"}, {"iast": "sarvatra-gaḥ", "sa": "सर्वत्रगः", "gram": "nom. sg. m. comp.", "es": "que va por todas partes", "analisis": "sarvatra (en todas partes) + ga (que va)"}, {"iast": "mahān", "sa": "महान्", "gram": "nom. sg. m.", "es": "grande"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "nom. pl. n.", "es": "todos"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres"}, {"iast": "mat-sthāni", "sa": "मत्स्थानि", "gram": "nom. pl. n. comp.", "es": "están en mí", "analisis": "mad (yo) + stha (que está)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "upadhāraya", "sa": "उपधारय", "gram": "2 sg. impv. caus.", "es": "compréndelo, tenlo presente", "analisis": "upa-√dhṛ (caus.: retener, comprender)"}], "nota": "<p><em>Ākāśa</em> es el espacio, el quinto de los elementos (<a class=\"vref\" href=\"capitulo-07.html#v4\" data-v=\"7.4\">7.4</a>), que todo lo contiene sin mezclarse con nada. La imagen explica la paradoja de los dos versos anteriores: el viento se mueve por todas partes dentro del espacio, pero el espacio no se mueve con él ni queda tocado por él. Así están los seres en Kṛṣṇa. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee la imagen de otro modo: el viento se mantiene en el espacio sin apoyo visible porque Kṛṣṇa lo sostiene, y así sostiene a todos los seres.</p>", "interp": [{"titulo": "El viento y el espacio", "html": "<p>La comparación sirve a la vez para las dos mitades de la paradoja: el viento está «en» el espacio, como los seres están en Kṛṣṇa; pero el espacio no sufre nada de lo que hace el viento, como Kṛṣṇa no está «en» los seres ni lo afectan. Así la leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: los seres están en él «sin contacto». <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> subraya otra cosa: el viento, que no tiene apoyo en el espacio, se mantiene porque el Señor lo sostiene. La Gītā volverá a la imagen del espacio en <a class=\"vref\" href=\"capitulo-13.html#v32\" data-v=\"13.32\">13.32</a>: como el espacio, por su sutileza, no se mancha, así el sí-mismo no se mancha, aunque esté en todo cuerpo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "como-el-viento-en-el-espacio"}, {"n": 7, "hablante": "krsna", "sa": ["सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम् ।", "कल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम् ॥७॥"], "iast": ["sarva-bhūtāni kaunteya prakṛtiṃ yānti māmikām", "kalpa-kṣaye punas tāni kalpādau visṛjāmy aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Al acabarse un <a class=\"t\" href=\"glosario.html#kalpa\" data-t=\"kalpa\">kalpa</a>, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, todos los seres entran en mi <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>; al comienzo de otro kalpa, yo los emito de nuevo.</span>", "palabras": [{"iast": "sarva-bhūtāni", "sa": "सर्वभूतानि", "gram": "nom. pl. n. comp.", "es": "todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh hijo de Kuntī", "ref": "kaunteya"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "a la naturaleza", "ref": "prakrti"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van, entran", "analisis": "√yā (ir)"}, {"iast": "māmikām", "sa": "मामिकाम्", "gram": "ac. sg. f.", "es": "mía", "analisis": "adjetivo posesivo derivado de mām (a mí)"}, {"iast": "kalpa-kṣaye", "sa": "कल्पक्षये", "gram": "loc. sg. m. comp.", "es": "al acabarse un kalpa", "ref": "kalpa", "analisis": "kalpa (día de Brahmā) + kṣaya (fin, destrucción)"}, {"iast": "punar", "sa": "पुनर्", "gram": "ind.", "es": "de nuevo"}, {"iast": "tāni", "sa": "तानि", "gram": "ac. pl. n.", "es": "a ellos"}, {"iast": "kalpādau", "sa": "कल्पादौ", "gram": "loc. sg. m. comp.", "es": "al comienzo de un kalpa", "ref": "kalpa", "analisis": "kalpa + ādi (comienzo)"}, {"iast": "visṛjāmi", "sa": "विसृजामि", "gram": "1 sg. pres. act.", "es": "emito", "ref": "visarga", "analisis": "vi + √sṛj (soltar, emitir)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}], "nota": "<p><em>Kalpa-kṣaye</em>: «al acabarse un kalpa», es decir, al final del día de Brahmā (<a class=\"vref\" href=\"capitulo-08.html#v17\" data-v=\"8.17\">8.17</a>–<a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>; véase <a class=\"t\" href=\"glosario.html#kalpa\" data-t=\"kalpa\">kalpa</a>); <em>kalpādau</em>, «al comienzo de un kalpa». Lo que <a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a> llamaba disolverse en lo no manifiesto (<a class=\"t\" href=\"glosario.html#pralaya\" data-t=\"pralaya\">pralaya</a>) es aquí entrar en la naturaleza de Kṛṣṇa: <em>māmikām</em>, «mía», como en <a class=\"vref\" href=\"capitulo-07.html#v4\" data-v=\"7.4\">7.4</a>–<a class=\"vref\" href=\"capitulo-07.html#v5\" data-v=\"7.5\">7.5</a>. <em>Visṛjāmi</em>, «emito», es del mismo verbo que <a class=\"t\" href=\"glosario.html#visarga\" data-t=\"visarga\">visarga</a> (<a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>).</p>", "interp": [{"titulo": "El ciclo en primera persona", "html": "<p>En <a class=\"vref\" href=\"capitulo-08.html#v17\" data-v=\"8.17\">8.17</a>–<a class=\"vref\" href=\"capitulo-08.html#v19\" data-v=\"8.19\">8.19</a> el día y la noche de Brahmā se describían de modo impersonal: los seres surgen y se disuelven. Aquí Kṛṣṇa dice lo mismo en primera persona: los seres entran en <em>su</em> naturaleza, y es <em>él</em> quien los emite. El ciclo cósmico no es un mecanismo ajeno a él, sino el despliegue y el repliegue de su propia naturaleza, como ya había dicho: «yo soy el origen del mundo entero, y también su disolución» (<a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La naturaleza inferior", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> precisa que la naturaleza en la que entran los seres es la inferior, la hecha de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, la que <a class=\"vref\" href=\"capitulo-07.html#v4\" data-v=\"7.4\">7.4</a> enumeraba en ocho partes. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la dicen también hecha de las tres guṇas, pero no la llaman inferior, sino māyā.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "emite-sin-quedar-atado"}, {"n": 8, "hablante": "krsna", "sa": ["प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः ।", "भूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात् ॥८॥"], "iast": ["prakṛtiṃ svām avaṣṭabhya visṛjāmi punaḥ punaḥ", "bhūta-grāmam imaṃ kṛtsnam avaśaṃ prakṛter vaśāt"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Apoyándome en mi propia <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a>, emito una y otra vez toda esta multitud de seres, que, sin poder evitarlo, está sometida al poder de la naturaleza.</span>", "palabras": [{"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "en la naturaleza", "ref": "prakrti"}, {"iast": "svām", "sa": "स्वाम्", "gram": "ac. sg. f.", "es": "propia"}, {"iast": "avaṣṭabhya", "sa": "अवष्टभ्य", "gram": "abs.", "es": "apoyándome en, sujetando", "analisis": "ava + √stambh (sostener, afirmar)"}, {"iast": "visṛjāmi", "sa": "विसृजामि", "gram": "1 sg. pres. act.", "es": "emito", "ref": "visarga", "analisis": "vi + √sṛj (soltar, emitir)"}, {"iast": "punaḥ punaḥ", "sa": "पुनः पुनः", "gram": "ind.", "es": "una y otra vez"}, {"iast": "bhūta-grāmam", "sa": "भूतग्रामम्", "gram": "ac. sg. m. comp.", "es": "la multitud de los seres", "analisis": "bhūta (ser) + grāma (conjunto, multitud)"}, {"iast": "imam", "sa": "इमम्", "gram": "ac. sg. m.", "es": "esta"}, {"iast": "kṛtsnam", "sa": "कृत्स्नम्", "gram": "ac. sg. m.", "es": "entera"}, {"iast": "avaśam", "sa": "अवशम्", "gram": "ac. sg. m.", "es": "sin voluntad propia, sin poder evitarlo", "analisis": "a (sin) + vaśa (poder, voluntad)"}, {"iast": "prakṛteḥ", "sa": "प्रकृतेः", "gram": "gen. sg. f.", "es": "de la naturaleza", "ref": "prakrti"}, {"iast": "vaśāt", "sa": "वशात्", "gram": "abl. sg. m.", "es": "por el poder", "analisis": "vaśa (poder, dominio)"}], "nota": "<p>«Mi propia naturaleza», <em>prakṛtiṃ svām</em>, es la misma expresión de <a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>, donde Kṛṣṇa nace «apoyándose en su propia naturaleza». <em>Avaśa</em>: «sin voluntad propia, sin poder evitarlo», como en <a class=\"vref\" href=\"capitulo-08.html#v19\" data-v=\"8.19\">8.19</a>. <em>Prakṛter vaśāt</em>, «por el poder de la naturaleza», puede entenderse como la misma naturaleza de Kṛṣṇa del comienzo del verso (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que la llama māyā) o como la naturaleza propia de cada ser (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>), sus tendencias formadas por las acciones pasadas (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>). El juego de palabras <em>avaśam… vaśāt</em>, «sin poder… por el poder», subraya el contraste: Kṛṣṇa se apoya en su naturaleza; los seres están a merced de ella.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "emite-sin-quedar-atado"}, {"n": 9, "hablante": "krsna", "sa": ["न च मां तानि कर्माणि निबध्नन्ति धनञ्जय ।", "उदासीनवदासीनमसक्तं तेषु कर्मसु ॥९॥"], "iast": ["na ca māṃ tāni karmāṇi nibadhnanti dhanañjaya", "udāsīna-vad āsīnam asaktaṃ teṣu karmasu"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y esas <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> no me atan, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>, a mí, que permanezco como quien se mantiene al margen, sin apego a ellas.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "tāni", "sa": "तानि", "gram": "nom. pl. n.", "es": "esas"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "nom. pl. n.", "es": "acciones", "ref": "karma"}, {"iast": "nibadhnanti", "sa": "निबध्नन्ति", "gram": "3 pl. pres. act.", "es": "atan", "analisis": "ni + √bandh (atar)"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh conquistador de riquezas", "ref": "dhananjaya"}, {"iast": "udāsīna-vat", "sa": "उदासीनवत्", "gram": "ind.", "es": "como el indiferente", "analisis": "udāsīna (el que se sienta aparte, el neutral; ud + √ās) + vat (como)"}, {"iast": "āsīnam", "sa": "आसीनम्", "gram": "ac. sg. m. part. pres. med.", "es": "que permanece, sentado", "analisis": "√ās (sentarse, permanecer)"}, {"iast": "asaktam", "sa": "असक्तम्", "gram": "ac. sg. m.", "es": "sin apego", "analisis": "a (sin) + sakta (apegado; √sañj)"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. n.", "es": "a esas"}, {"iast": "karmasu", "sa": "कर्मसु", "gram": "loc. pl. n.", "es": "acciones", "ref": "karma"}], "nota": "<p><em>Udāsīna</em>, de ud-√ās, «sentarse aparte»: el que no toma partido, el neutral; el verso juega con <em>āsīnam</em>, «que permanece, sentado». El sufijo <em>-vat</em>, «como», deja abierto si Kṛṣṇa es de verdad indiferente o sólo se comporta como quien lo es: <a class=\"vref\" href=\"capitulo-09.html#v29\" data-v=\"9.29\">9.29</a> dirá que es igual para todos los seres, pero que los que lo adoran están en él y él en ellos. La misma expresión, <em>udāsīnavad āsīnaḥ</em>, describe en <a class=\"vref\" href=\"capitulo-14.html#v23\" data-v=\"14.23\">14.23</a> al que ha ido más allá de las guṇas.</p>", "interp": [{"titulo": "Lo que pide al yogui, lo hace él", "html": "<p>Kṛṣṇa aplica a su propia actividad cósmica lo que viene pidiendo a Arjuna: obrar sin apego (<em>asakta</em>, como en <a class=\"vref\" href=\"capitulo-03.html#v19\" data-v=\"3.19\">3.19</a>). Ya lo había dicho de sí mismo en <a class=\"vref\" href=\"capitulo-03.html#v22\" data-v=\"3.22\">3.22</a>, «no tengo nada que hacer, y sin embargo actúo», y en <a class=\"vref\" href=\"capitulo-04.html#v14\" data-v=\"4.14\">4.14</a>, «las acciones no me manchan». Lo que en el hombre es una disciplina, en el Señor es su manera de ser.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "emite-sin-quedar-atado"}, {"n": 10, "hablante": "krsna", "sa": ["मयाध्यक्षेण प्रकृतिः सूयते सचराचरम् ।", "हेतुनानेन कौन्तेय जगद्विपरिवर्तते ॥१०॥"], "iast": ["mayādhyakṣeṇa prakṛtiḥ sūyate sa-carācaram", "hetunānena kaunteya jagad viparivartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Bajo mi supervisión, la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> engendra lo móvil y lo inmóvil; por esta causa, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, gira el mundo.</span>", "palabras": [{"iast": "mayā", "sa": "मया", "gram": "instr. sg.", "es": "por mí"}, {"iast": "adhyakṣeṇa", "sa": "अध्यक्षेण", "gram": "instr. sg. m.", "es": "como supervisor", "analisis": "adhi (sobre) + akṣa (ojo): «el que tiene el ojo encima», el que preside"}, {"iast": "prakṛtiḥ", "sa": "प्रकृतिः", "gram": "nom. sg. f.", "es": "la naturaleza", "ref": "prakrti"}, {"iast": "sūyate", "sa": "सूयते", "gram": "3 sg. pres. med.", "es": "engendra, da a luz", "analisis": "√sū (engendrar, parir)"}, {"iast": "sa-carācaram", "sa": "सचराचरम्", "gram": "ac. sg. n. comp.", "es": "con lo móvil y lo inmóvil", "analisis": "sa (con) + cara (móvil) + acara (inmóvil)"}, {"iast": "hetunā", "sa": "हेतुना", "gram": "instr. sg. m.", "es": "por causa"}, {"iast": "anena", "sa": "अनेन", "gram": "instr. sg. m.", "es": "de esto, por esta"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh hijo de Kuntī", "ref": "kaunteya"}, {"iast": "jagat", "sa": "जगत्", "gram": "nom. sg. n.", "es": "el mundo", "analisis": "√gam (ir): «lo que se mueve»"}, {"iast": "viparivartate", "sa": "विपरिवर्तते", "gram": "3 sg. pres. med.", "es": "gira, da vueltas", "analisis": "vi + pari + √vṛt (girar)"}], "nota": "<p><em>Adhyakṣa</em>, «el que supervisa», es literalmente «el que tiene el ojo (<em>akṣa</em>) encima»: el que preside, el inspector. <em>Sūyate</em>, de √sū, «engendrar, dar a luz»: la naturaleza es aquí madre, como en <a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>–<a class=\"vref\" href=\"capitulo-14.html#v4\" data-v=\"14.4\">14.4</a>, donde Kṛṣṇa pone el germen en la gran matriz. <em>Sa-carācaram</em>, «con lo móvil y lo inmóvil», es el mundo entero, los animales y las plantas. <em>Jagat</em>, «el mundo», es «lo que se mueve», y el verso termina con un verbo de giro: el mundo da vueltas.</p>", "interp": [{"titulo": "Un testigo que no obra", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>adhyakṣa</em> como el que sólo ve: el Señor, cuya naturaleza es pura conciencia, no hace nada; en su sola presencia, la naturaleza —su <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>, hecha de las tres guṇas— produce el mundo. Así resuelve la contradicción entre «emito» (<a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a>) y «como quien se mantiene al margen» (<a class=\"vref\" href=\"capitulo-09.html#v9\" data-v=\"9.9\">9.9</a>): Kṛṣṇa emite los seres sin actuar. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica con las mismas palabras.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El modelo del Sāṅkhya", "html": "<p>El reparto de papeles recuerda el del <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">Sāṅkhya</a> clásico, en el que la naturaleza obra y el espíritu sólo presencia: las <em>Sāṅkhya-kārikā</em> (19) atribuyen al <em>puruṣa</em> la condición de testigo, de neutral y de no agente. La Gītā conserva la imagen, pero cambia al espectador: quien preside la naturaleza no es cada espíritu individual, sino el Señor.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Ante mí, que sólo la contemplo, la naturaleza engendra lo móvil y lo inmóvil; por esta causa, oh Kaunteya, gira el mundo.", "nota": "<p>Si <em>adhyakṣa</em> se entiende como el testigo que preside sin intervenir, la naturaleza obra por sí misma en su presencia, y el Señor sigue siendo el «indiferente» del verso anterior. Así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que glosan <em>adhyakṣa</em> como aquel «cuya naturaleza es sólo ver».</p>"}, {"html": "Dirigida por mí, la naturaleza engendra lo móvil y lo inmóvil; por esta causa, oh Kaunteya, gira el mundo.", "nota": "<p>Si se subraya que la naturaleza obra porque el Señor la gobierna y la pone en movimiento, como dice el propio Kṛṣṇa en <a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a> («emito una y otra vez…»). Así <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, para quien Kṛṣṇa no sólo ve, sino que hace engendrar a la naturaleza, que no obra por sí misma; y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien la naturaleza engendra al ser mirada por el Señor, cuya voluntad se cumple siempre, conforme a las acciones de los seres. Es la lectura de <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: la naturaleza engendra el mundo bajo la mirada del Señor, de voluntad infalible, conforme a las acciones de los seres. La traducción principal, «bajo mi supervisión», deja abiertas las dos lecturas.</p>"}], "ens": "emite-sin-quedar-atado"}, {"n": 11, "hablante": "krsna", "sa": ["अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम् ।", "परं भावमजानन्तो मम भूतमहेश्वरम् ॥११॥"], "iast": ["avajānanti māṃ mūḍhā mānuṣīṃ tanum āśritam", "paraṃ bhāvam ajānanto mama bhūta-maheśvaram"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">necios</a> me desprecian cuando he tomado un cuerpo humano, sin conocer mi estado supremo de <a class=\"t\" href=\"glosario.html#mahesvara\" data-t=\"mahesvara\">gran Señor de los seres</a>.</span>", "palabras": [{"iast": "avajānanti", "sa": "अवजानन्ति", "gram": "3 pl. pres. act.", "es": "desprecian, menosprecian", "analisis": "ava (abajo) + √jñā (conocer): «conocer por debajo»"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "mūḍhāḥ", "sa": "मूढाः", "gram": "nom. pl. m.", "es": "los necios, los extraviados", "ref": "moha", "analisis": "√muh (extraviarse)"}, {"iast": "mānuṣīm", "sa": "मानुषीम्", "gram": "ac. sg. f.", "es": "humano", "analisis": "mānuṣa (humano), de manu"}, {"iast": "tanum", "sa": "तनुम्", "gram": "ac. sg. f.", "es": "un cuerpo"}, {"iast": "āśritam", "sa": "आश्रितम्", "gram": "ac. sg. m. part. pas.", "es": "que ha tomado, que se ha acogido a", "analisis": "ā + √śri (apoyarse, acogerse)"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. m.", "es": "supremo"}, {"iast": "bhāvam", "sa": "भावम्", "gram": "ac. sg. m.", "es": "estado, naturaleza", "analisis": "√bhū (ser)"}, {"iast": "ajānantaḥ", "sa": "अजानन्तः", "gram": "nom. pl. m. part. pres.", "es": "sin conocer", "analisis": "a (no) + jānat (que conoce; √jñā)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg.", "es": "mi"}, {"iast": "bhūta-maheśvaram", "sa": "भूतमहेश्वरम्", "gram": "ac. sg. m. comp.", "es": "gran Señor de los seres", "ref": "mahesvara", "analisis": "bhūta (ser) + mahā (grande) + īśvara (señor)"}], "nota": "<p><em>Avajānanti</em>: «desprecian, menosprecian», de ava-√jñā, literalmente «conocer por debajo». <em>Mānuṣīṃ tanum āśritam</em>: «que ha tomado (literalmente, “que se ha acogido a”) un cuerpo humano». <em>Paraṃ bhāvam</em>, «mi estado supremo», es la misma expresión de <a class=\"vref\" href=\"capitulo-07.html#v24\" data-v=\"7.24\">7.24</a>; <em>bhūta-maheśvara</em>, «gran Señor de los seres», la de la ficha <a class=\"t\" href=\"glosario.html#mahesvara\" data-t=\"mahesvara\">Maheśvara</a>.</p>", "interp": [{"titulo": "El Señor con forma humana", "html": "<p>Es la misma queja de <a class=\"vref\" href=\"capitulo-07.html#v24\" data-v=\"7.24\">7.24</a>–<a class=\"vref\" href=\"capitulo-07.html#v25\" data-v=\"7.25\">7.25</a>: los necios ven en Kṛṣṇa a un ser nacido como los demás, porque no conocen su «estado supremo». Lo que los extravía es justamente lo que <a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>–<a class=\"vref\" href=\"capitulo-04.html#v8\" data-v=\"4.8\">4.8</a> presentaba como un don: que el Señor descienda y tome cuerpo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Un cuerpo que no es material", "html": "<p>Para la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, la forma humana de Kṛṣṇa no es un cuerpo material como el de los demás, sino su forma eterna, «hecha de ser, conciencia y dicha» (<em>sac-cid-ānanda-vigraha</em>, <em>Brahma-saṃhitā</em> 5.1); despreciarla es tomarla por material.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los necios me desprecian porque me ven con apariencia humana, sin conocer mi estado supremo de gran Señor de los seres.", "nota": "<p><em>Āśrita</em>, «que se ha acogido a», no dice si el cuerpo es real o aparente. La alternativa va en la línea de lo que <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> dice del nacimiento de Kṛṣṇa en <a class=\"vref\" href=\"capitulo-04.html#v6\" data-v=\"4.6\">4.6</a>: nace «como si tuviera cuerpo, como si naciera». <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, entiende allí un nacimiento real, por su propia voluntad y sin perder su condición divina. En 9.11 mismo, <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa sólo «que actúa por medio de un cuerpo humano»; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> habla de una forma «que se percibe como humana», tomada por su voluntad para favorecer a los devotos, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, de un cuerpo de puro sattva con forma humana. La traducción principal, «cuando he tomado un cuerpo humano», no decide.</p>"}], "ens": "despreciado-en-forma-humana"}, {"n": 12, "hablante": "krsna", "sa": ["मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः ।", "राक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः ॥१२॥"], "iast": ["moghāśā mogha-karmāṇo mogha-jñānā vicetasaḥ", "rākṣasīm āsurīṃ caiva prakṛtiṃ mohinīṃ śritāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">De vanas esperanzas, vanas obras y vano <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a>, faltos de juicio, se acogen a una <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> que <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravía</a>, propia de los <a class=\"t\" href=\"glosario.html#raksasa\" data-t=\"raksasa\">rākṣasas</a> y de los <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">demonios</a>.</span>", "palabras": [{"iast": "moghāśāḥ", "sa": "मोघाशाः", "gram": "nom. pl. m. comp.", "es": "de vanas esperanzas", "analisis": "mogha (vano) + āśā (esperanza)"}, {"iast": "mogha-karmāṇaḥ", "sa": "मोघकर्माणः", "gram": "nom. pl. m. comp.", "es": "de vanas obras", "ref": "karma", "analisis": "mogha (vano) + karman (acción)"}, {"iast": "mogha-jñānāḥ", "sa": "मोघज्ञानाः", "gram": "nom. pl. m. comp.", "es": "de vano conocimiento", "ref": "jnana", "analisis": "mogha (vano) + jñāna (conocimiento)"}, {"iast": "vicetasaḥ", "sa": "विचेतसः", "gram": "nom. pl. m.", "es": "faltos de juicio", "analisis": "vi (sin) + cetas (mente, juicio)"}, {"iast": "rākṣasīm", "sa": "राक्षसीम्", "gram": "ac. sg. f.", "es": "de los rākṣasas", "ref": "raksasa", "analisis": "rākṣasa (propio de los rakṣas)"}, {"iast": "āsurīm", "sa": "आसुरीम्", "gram": "ac. sg. f.", "es": "demoníaca", "ref": "asura", "analisis": "āsura (propio de los asuras)"}, {"iast": "caiva", "sa": "चैव", "gram": "ind.", "es": "y también", "analisis": "ca (y) + eva (también, precisamente)"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "una naturaleza", "ref": "prakrti"}, {"iast": "mohinīm", "sa": "मोहिनीम्", "gram": "ac. sg. f.", "es": "que extravía", "ref": "moha", "analisis": "√muh (extraviarse)"}, {"iast": "śritāḥ", "sa": "श्रिताः", "gram": "nom. pl. m. part. pas.", "es": "acogidos a", "analisis": "√śri (apoyarse, acogerse)"}], "nota": "<p><em>Mogha</em>, «vano, sin fruto», se repite tres veces: esperanzas, acciones y conocimientos que no llevan a nada. <em>Vicetasaḥ</em>: «faltos de juicio», sin discernimiento. <em>Mohinī</em>, «que extravía», es del mismo verbo que <em>moha</em> y que los «necios» (<em>mūḍha</em>) de <a class=\"vref\" href=\"capitulo-09.html#v11\" data-v=\"9.11\">9.11</a>, que siguen siendo el sujeto. La naturaleza de los <a class=\"t\" href=\"glosario.html#raksasa\" data-t=\"raksasa\">rākṣasas</a> y de los <a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">asuras</a> es la condición «demoníaca» de <a class=\"vref\" href=\"capitulo-07.html#v15\" data-v=\"7.15\">7.15</a>, que el capítulo 16 describirá por extenso (<a class=\"vref\" href=\"capitulo-16.html#v4\" data-v=\"16.4\">16.4</a>; <a class=\"vref\" href=\"capitulo-16.html#v6\" data-v=\"16.6\">16.6</a>–<a class=\"vref\" href=\"capitulo-16.html#v20\" data-v=\"16.20\">16.20</a>).</p>", "interp": [{"titulo": "Dos clases de extravío", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> distinguen las dos naturalezas del verso: la de los rākṣasas, en la que domina <a class=\"t\" href=\"glosario.html#tamas\" data-t=\"tamas\">tamas</a> y que lleva a la violencia, y la de los asuras, en la que domina <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> y que lleva al deseo y a la soberbia. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no habla aquí de guṇas: es la naturaleza que toma el cuerpo por el sí-mismo y hace decir «corta, rompe, bebe, come, roba lo ajeno».</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "despreciado-en-forma-humana"}, {"n": 13, "hablante": "krsna", "sa": ["महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः ।", "भजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् ॥१३॥"], "iast": ["mahātmānas tu māṃ pārtha daivīṃ prakṛtim āśritāḥ", "bhajanty ananya-manaso jñātvā bhūtādim avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero los <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">grandes seres</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, acogidos a la <a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">naturaleza</a> divina, me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a> con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> puesta en nada más, sabiendo que soy el origen imperecedero de los seres.</span>", "palabras": [{"iast": "mahātmānaḥ", "sa": "महात्मानः", "gram": "nom. pl. m.", "es": "los grandes seres", "ref": "mahatman", "analisis": "mahat (grande) + ātman (sí-mismo, ánimo)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "daivīm", "sa": "दैवीम्", "gram": "ac. sg. f. adj.", "es": "divina", "ref": "deva", "analisis": "daiva (de los dioses, divino)"}, {"iast": "prakṛtim", "sa": "प्रकृतिम्", "gram": "ac. sg. f.", "es": "naturaleza", "ref": "prakrti", "analisis": "pra + √kṛ (hacer)"}, {"iast": "āśritāḥ", "sa": "आश्रिताः", "gram": "nom. pl. m. ppp", "es": "acogidos a", "analisis": "ā + √śri (apoyarse, refugiarse)"}, {"iast": "bhajanti", "sa": "भजन्ति", "gram": "3 pl. pres. act.", "es": "adoran", "ref": "bhakti", "analisis": "√bhaj (participar, adorar), de donde bhakti"}, {"iast": "ananya-manasaḥ", "sa": "अनन्यमनसः", "gram": "nom. pl. m. comp.", "es": "con la mente puesta en nada más", "ref": "manas", "analisis": "an-anya (no otro) + manas (mente)"}, {"iast": "jñātvā", "sa": "ज्ञात्वा", "gram": "abs.", "es": "conociendo, sabiendo", "analisis": "√jñā (conocer)"}, {"iast": "bhūtādim", "sa": "भूतादिम्", "gram": "ac. sg. m. comp.", "es": "el origen de los seres", "analisis": "bhūta (ser) + ādi (comienzo, origen)"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m. adj.", "es": "imperecedero", "analisis": "a (no) + vi-√i (desaparecer)"}], "nota": "<p><em>Daivī prakṛti</em>, «la naturaleza divina», se opone a la naturaleza «de los rākṣasas y los asuras» del verso anterior (<a class=\"vref\" href=\"capitulo-09.html#v12\" data-v=\"9.12\">9.12</a>): no es aquí la naturaleza material, sino una disposición del ánimo. El capítulo 16 desarrollará la oposición entre las dos (<a class=\"vref\" href=\"capitulo-16.html#v1\" data-v=\"16.1\">16.1</a>–<a class=\"vref\" href=\"capitulo-16.html#v6\" data-v=\"16.6\">16.6</a>). <em>Ananya-manas</em>: «el que no tiene otra mente», es decir, cuya mente no se vuelve a otra cosa; la misma idea de exclusividad que en <a class=\"vref\" href=\"capitulo-08.html#v14\" data-v=\"8.14\">8.14</a> y <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a>. <em>Bhūtādi</em>: «el comienzo de los seres», su origen o causa: para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, de los elementos, empezando por el espacio, y de los seres vivos; para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, del mundo entero. <em>Avyaya</em>: «imperecedero», que no se gasta.</p>", "interp": [{"titulo": "Dos naturalezas", "html": "<p>Los versos <a class=\"vref\" href=\"capitulo-09.html#v11\" data-v=\"9.11\">9.11</a>–<a class=\"vref\" href=\"capitulo-09.html#v13\" data-v=\"9.13\">9.13</a> presentan dos maneras de estar ante Kṛṣṇa cuando se muestra en forma humana. Los necios lo desprecian y se acogen a una naturaleza de demonios (<a class=\"t\" href=\"glosario.html#asura\" data-t=\"asura\">asura</a>); los grandes seres, acogidos a la naturaleza divina, lo adoran. La diferencia no está en lo que ven, sino en la disposición con que lo miran. Es el primer esbozo de la doctrina de las dos herencias, la divina y la demoníaca, que ocupará el capítulo 16.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "como-lo-adoran-los-grandes-seres"}, {"n": 14, "hablante": "krsna", "sa": ["सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः ।", "नमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते ॥१४॥"], "iast": ["satataṃ kīrtayanto māṃ yatantaś ca dṛḍha-vratāḥ", "namasyantaś ca māṃ bhaktyā nitya-yuktā upāsate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Glorificándome sin cesar, esforzándose, firmes en sus votos, inclinándose ante mí con <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>, siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unidos</a>, me veneran.</span>", "palabras": [{"iast": "satatam", "sa": "सततम्", "gram": "ind.", "es": "siempre, sin cesar"}, {"iast": "kīrtayantaḥ", "sa": "कीर्तयन्तः", "gram": "nom. pl. m. part. pres.", "es": "glorificando, alabando", "analisis": "√kīrt (mencionar, celebrar), de donde kīrtana"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "yatantaḥ", "sa": "यतन्तः", "gram": "nom. pl. m. part. pres.", "es": "esforzándose", "analisis": "√yat (esforzarse)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "dṛḍha-vratāḥ", "sa": "दृढव्रताः", "gram": "nom. pl. m. comp.", "es": "firmes en sus votos", "analisis": "dṛḍha (firme) + vrata (voto, observancia)"}, {"iast": "namasyantaḥ", "sa": "नमस्यन्तः", "gram": "nom. pl. m. part. pres.", "es": "inclinándose, rindiendo homenaje", "analisis": "denominativo de namas (reverencia)"}, {"iast": "bhaktyā", "sa": "भक्त्या", "gram": "instr. sg. f.", "es": "con devoción", "ref": "bhakti"}, {"iast": "nitya-yuktāḥ", "sa": "नित्ययुक्ताः", "gram": "nom. pl. m. comp.", "es": "siempre unidos", "ref": "yukta", "analisis": "nitya (constante) + yukta (unido)"}, {"iast": "upāsate", "sa": "उपासते", "gram": "3 pl. pres. med.", "es": "veneran", "analisis": "upa + √ās (sentarse junto a; servir, venerar)"}], "nota": "<p><em>Kīrtayantaḥ</em>, de √kīrt, «mencionar, celebrar»: glorificar a Kṛṣṇa nombrándolo o cantando sus cualidades; de la misma raíz viene <em>kīrtana</em>, el canto devocional. <em>Dṛḍha-vrata</em>: «de votos firmes», el que mantiene sus observancias, como el ayuno o la disciplina diaria. <em>Upāsate</em>, de upa-√ās, «sentarse junto a»: servir, venerar; de la misma familia que <em>upāsanā</em>, la meditación devota de las Upaniṣads. Glorificar, esforzarse, guardar los votos e inclinarse son cuatro gestos que la devoción posterior desarrollará en formas de culto.</p>", "interp": [{"titulo": "El canto de los nombres", "html": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, que remonta a <a class=\"t\" href=\"glosario.html#caitanya\" data-t=\"caitanya\">Caitanya</a>, hace del canto en común de los nombres de Dios (<em>saṅkīrtana</em>) la práctica central de la devoción, y lo reconoce en el <em>kīrtayantaḥ</em> de este verso. Prabhupāda, en su comentario, lo entiende como la glorificación constante de Kṛṣṇa —su nombre, su forma, sus cualidades y sus actos—, dentro de la devoción que empieza por «oír y cantar» (<em>śravaṇaṃ kīrtanaṃ viṣṇoḥ</em>). Viśvanātha Cakravartī ve en los «votos firmes» el propósito de cantar cada día un número fijo de rondas del nombre.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "como-lo-adoran-los-grandes-seres"}, {"n": 15, "hablante": "krsna", "sa": ["ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते ।", "एकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम् ॥१५॥"], "iast": ["jñāna-yajñena cāpy anye yajanto mām upāsate", "ekatvena pṛthaktvena bahudhā viśvato-mukham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Otros, ofreciendo el <a class=\"t\" href=\"glosario.html#jnana-yajna\" data-t=\"jnana-yajna\">sacrificio del conocimiento</a>, me veneran también a mí, cuyo rostro mira a todas partes: como uno, como distinto, de muchas maneras.</span>", "palabras": [{"iast": "jñāna-yajñena", "sa": "ज्ञानयज्ञेन", "gram": "instr. sg. m. comp.", "es": "con el sacrificio del conocimiento", "ref": "jnana-yajna", "analisis": "jñāna (conocimiento) + yajña (sacrificio)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "anye", "sa": "अन्ये", "gram": "nom. pl. m. pron.", "es": "otros"}, {"iast": "yajantaḥ", "sa": "यजन्तः", "gram": "nom. pl. m. part. pres.", "es": "sacrificando, ofreciendo", "analisis": "√yaj (sacrificar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "upāsate", "sa": "उपासते", "gram": "3 pl. pres. med.", "es": "veneran", "analisis": "upa + √ās"}, {"iast": "ekatvena", "sa": "एकत्वेन", "gram": "instr. sg. n.", "es": "como uno, en la unidad", "analisis": "eka (uno) + -tva (cualidad): «unidad»"}, {"iast": "pṛthaktvena", "sa": "पृथक्त्वेन", "gram": "instr. sg. n.", "es": "como distinto, en la separación", "analisis": "pṛthak (aparte) + -tva: «distinción»"}, {"iast": "bahudhā", "sa": "बहुधा", "gram": "ind.", "es": "de muchas maneras", "analisis": "bahu (mucho) + -dhā (de modo)"}, {"iast": "viśvato-mukham", "sa": "विश्वतोमुखम्", "gram": "ac. sg. m. comp.", "es": "cuyo rostro mira a todas partes", "analisis": "viśvataḥ (por todas partes) + mukha (rostro)"}], "nota": "<p>El <a class=\"t\" href=\"glosario.html#jnana-yajna\" data-t=\"jnana-yajna\">sacrificio del conocimiento</a> ya fue alabado en <a class=\"vref\" href=\"capitulo-04.html#v33\" data-v=\"4.33\">4.33</a>: es el que no ofrece bienes, sino el propio conocer. Los tres adverbios del segundo verso, <em>ekatvena</em>, «en cuanto uno», <em>pṛthaktvena</em>, «en cuanto distinto», y <em>bahudhā</em>, «de muchas maneras», pueden referirse a cómo veneran los adoradores o a cómo es aquel a quien veneran; la traducción conserva la ambigüedad (véanse las alternativas). <em>Viśvato-mukha</em>, «que tiene el rostro en todas direcciones», anuncia la forma universal del capítulo 11 (<a class=\"vref\" href=\"capitulo-11.html#v11\" data-v=\"11.11\">11.11</a>).</p>", "interp": [{"titulo": "Tres maneras de venerar", "html": "<p>Tras los grandes seres que adoran con devoción (<a class=\"vref\" href=\"capitulo-09.html#v13\" data-v=\"9.13\">9.13</a>–<a class=\"vref\" href=\"capitulo-09.html#v14\" data-v=\"9.14\">9.14</a>), el verso añade a los que adoran por el conocimiento, y no distingue entre una vía y otra: los dos son formas de venerar a Kṛṣṇa. La Gītā vuelve a acoger, como en <a class=\"vref\" href=\"capitulo-04.html#v11\" data-v=\"4.11\">4.11</a> y <a class=\"vref\" href=\"capitulo-07.html#v21\" data-v=\"7.21\">7.21</a>, la diversidad de los caminos dentro de una sola meta.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Otros, ofreciendo el sacrificio del conocimiento, me veneran también: unos en la unidad, sabiendo que no son distintos de mí; otros como distinto, en el sol, en la luna y en las demás divinidades; otros, de muchas maneras, a mí, cuya forma es el universo entero.", "nota": "<p>Así lo explica <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>: los tres adverbios no describen a Kṛṣṇa, sino tres clases de adoradores. Los primeros lo veneran con la visión de la realidad suprema, la unidad de todo; los segundos, en formas distintas, como el sol o la luna; los terceros, en su forma universal, vuelta hacia todas partes. También <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> ven tres clases de adoradores, aunque para Śrīdhara el segundo es el que se sabe siervo de Kṛṣṇa.</p>"}, {"html": "Otros, ofreciendo el sacrificio del conocimiento, me veneran también a mí, que soy uno y, en el universo, que es mi cuerpo, estoy presente de muchas maneras y bajo formas distintas, con el rostro vuelto hacia todas partes.", "nota": "<p>Así lo lee <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, que no ve aquí tres clases de adoradores, sino una sola manera de conocer a Kṛṣṇa: como el uno que, teniendo por cuerpo el mundo entero, se presenta en él de muchas maneras. También <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> refiere los adverbios a Kṛṣṇa, aunque de otro modo: uno, porque el mismo Nārāyaṇa está en todo; distinto, porque difiere de todo; múltiple, por sus muchas formas.</p>"}], "ens": "como-lo-adoran-los-grandes-seres"}, {"n": 16, "hablante": "krsna", "sa": ["अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम् ।", "मन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम् ॥१६॥"], "iast": ["ahaṃ kratur ahaṃ yajñaḥ svadhāham aham auṣadham", "mantro 'ham aham evājyam aham agnir ahaṃ hutam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo soy el rito, yo el <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificio</a>, yo la <a class=\"t\" href=\"glosario.html#svadha\" data-t=\"svadha\">ofrenda a los antepasados</a>, yo la planta; yo soy el <a class=\"t\" href=\"glosario.html#mantra\" data-t=\"mantra\">mantra</a>, yo la mantequilla clarificada, yo el <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">fuego</a>, yo la oblación.</span>", "palabras": [{"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "kratuḥ", "sa": "क्रतुः", "gram": "nom. sg. m.", "es": "el rito", "analisis": "kratu (rito védico; también fuerza, intención)"}, {"iast": "yajñaḥ", "sa": "यज्ञः", "gram": "nom. sg. m.", "es": "el sacrificio", "ref": "yajna", "analisis": "√yaj (sacrificar)"}, {"iast": "svadhā", "sa": "स्वधा", "gram": "nom. sg. f.", "es": "la ofrenda a los antepasados", "ref": "svadha", "analisis": "sva (propio) + √dhā (poner)"}, {"iast": "auṣadham", "sa": "औषधम्", "gram": "nom. sg. n.", "es": "la planta, la hierba", "analisis": "de oṣadhi (planta, hierba medicinal)"}, {"iast": "mantraḥ", "sa": "मन्त्रः", "gram": "nom. sg. m.", "es": "el mantra", "ref": "mantra", "analisis": "√man (pensar) + -tra (instrumento)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "ājyam", "sa": "आज्यम्", "gram": "nom. sg. n.", "es": "la mantequilla clarificada", "analisis": "ā + √añj (ungir): la grasa que se vierte en el fuego"}, {"iast": "agniḥ", "sa": "अग्निः", "gram": "nom. sg. m.", "es": "el fuego", "ref": "agni"}, {"iast": "hutam", "sa": "हुतम्", "gram": "nom. sg. n. ppp", "es": "la oblación, lo ofrecido", "analisis": "√hu (verter en el fuego, ofrecer)"}], "nota": "<p>Los ocho términos recorren el sacrificio védico entero. <em>Kratu</em> es el rito, en particular el sacrificio solemne del Veda; <em>yajña</em>, el sacrificio en general. <em>Svadhā</em> es la ofrenda a los antepasados, y también la exclamación con que se les ofrece, como <em>svāhā</em> para los dioses. <em>Auṣadha</em>, de <em>oṣadhi</em>, «planta», es la hierba o el grano del que se hace la ofrenda, y también el alimento de todos los seres, el arroz o la cebada (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>); <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> admiten también «la medicina». El <em>mantra</em> es la fórmula que se recita; <em>ājya</em>, la mantequilla clarificada que se vierte en el <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">fuego</a>; <em>huta</em>, «lo vertido», la oblación misma. Es la contrapartida, en primera persona, de <a class=\"vref\" href=\"capitulo-04.html#v24\" data-v=\"4.24\">4.24</a>: allí todos los elementos del sacrificio son <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>; aquí Kṛṣṇa dice «yo soy».</p>", "interp": [{"titulo": "El rito y el sacrificio", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, distingue los dos primeros términos: <em>kratu</em> es el rito prescrito en la revelación védica (<em>śrauta</em>); <em>yajña</em>, el sacrificio que prescribe la tradición (<em>smārta</em>). Los ejemplos son de Śrīdhara y Madhusūdana: el <em>agniṣṭoma</em> para el primero, los cinco grandes sacrificios de cada día para el segundo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Todo el sacrificio", "html": "<p>La serie «yo soy…» comenzó en <a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>–<a class=\"vref\" href=\"capitulo-07.html#v11\" data-v=\"7.11\">7.11</a>, donde Kṛṣṇa era lo esencial de cada cosa: el sabor del agua, la luz del sol. Aquí se concentra en el sacrificio, el centro de la religión védica: no es sólo su destinatario (<a class=\"vref\" href=\"capitulo-05.html#v29\" data-v=\"5.29\">5.29</a>, <a class=\"vref\" href=\"capitulo-09.html#v24\" data-v=\"9.24\">9.24</a>), sino cada uno de sus elementos. El capítulo 10 extenderá la serie a todo el mundo (<a class=\"vref\" href=\"capitulo-10.html#v20\" data-v=\"10.20\">10.20</a>–<a class=\"vref\" href=\"capitulo-10.html#v41\" data-v=\"10.41\">10.41</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "yo-soy-el-rito-y-el-mundo"}, {"n": 17, "hablante": "krsna", "sa": ["पिताहमस्य जगतो माता धाता पितामहः ।", "वेद्यं पवित्रमोंकार ऋक्साम यजुरेव च ॥१७॥"], "iast": ["pitāham asya jagato mātā dhātā pitāmahaḥ", "vedyaṃ pavitram oṃkāra ṛk sāma yajur eva ca"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo soy el padre de este mundo, la madre, el que lo sostiene, el abuelo; lo que ha de conocerse, el purificador, la sílaba <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a>, y también el Ṛg, el Sāma y el Yajus.</span>", "palabras": [{"iast": "pitā", "sa": "पिता", "gram": "nom. sg. m.", "es": "el padre", "ref": "pitr"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. n. pron.", "es": "de este"}, {"iast": "jagataḥ", "sa": "जगतः", "gram": "gen. sg. n.", "es": "mundo", "analisis": "jagat (lo que se mueve, el mundo), de √gam (ir)"}, {"iast": "mātā", "sa": "माता", "gram": "nom. sg. f.", "es": "la madre"}, {"iast": "dhātā", "sa": "धाता", "gram": "nom. sg. m.", "es": "el que sostiene, el que dispone", "analisis": "√dhā (poner, sostener, disponer)"}, {"iast": "pitāmahaḥ", "sa": "पितामहः", "gram": "nom. sg. m.", "es": "el abuelo", "analisis": "pitṛ (padre) + mahat (grande): «el gran padre»"}, {"iast": "vedyam", "sa": "वेद्यम्", "gram": "nom. sg. n. gerundivo", "es": "lo que ha de conocerse", "analisis": "√vid (conocer)"}, {"iast": "pavitram", "sa": "पवित्रम्", "gram": "nom. sg. n.", "es": "el purificador", "analisis": "√pū (purificar)"}, {"iast": "oṃkāraḥ", "sa": "ओंकारः", "gram": "nom. sg. m.", "es": "la sílaba oṃ", "ref": "om", "analisis": "om + kāra (la letra, el sonido)"}, {"iast": "ṛk", "sa": "ऋक्", "gram": "nom. sg. f.", "es": "el Ṛg (Veda)", "ref": "veda", "analisis": "ṛc (estrofa, himno)"}, {"iast": "sāma", "sa": "साम", "gram": "nom. sg. n.", "es": "el Sāma (Veda)", "ref": "veda", "analisis": "sāman (canto, melodía)"}, {"iast": "yajuḥ", "sa": "यजुः", "gram": "nom. sg. n.", "es": "el Yajus (Veda)", "ref": "veda", "analisis": "yajus (fórmula del sacrificio)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también, precisamente"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}], "nota": "<p><em>Dhātṛ</em>, de √dhā, «poner, sostener», es el que sostiene y el que dispone u ordena el mundo; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo glosan «el que dispensa a los seres el fruto de sus acciones», y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, «el que nutre» o eso mismo. <em>Pitāmaha</em>, «el gran padre», el abuelo, es título del creador <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>; Kṛṣṇa, que es el origen de Brahmā, es su padre, y Arjuna lo llamará <em>prapitāmaha</em>, «bisabuelo», en <a class=\"vref\" href=\"capitulo-11.html#v39\" data-v=\"11.39\">11.39</a>. <em>Pavitra</em>, «lo que purifica»: en <a class=\"vref\" href=\"capitulo-04.html#v38\" data-v=\"4.38\">4.38</a> nada hay tan purificador como el conocimiento. <em>Ṛk</em>, <em>sāma</em>, <em>yajuḥ</em>: los tres <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a> de la tradición antigua, la <a class=\"t\" href=\"glosario.html#trayi\" data-t=\"trayi\"><em>trayī</em></a>, el himno, el canto y la fórmula del sacrificio; el <em>Atharva</em> no se nombra, como tampoco en <a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>, aunque <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo ve incluido en el «y» (<em>ca</em>) final.</p>", "interp": [{"titulo": "Padre y madre", "html": "<p>Kṛṣṇa se dice a la vez padre y madre del mundo. En <a class=\"vref\" href=\"capitulo-14.html#v3\" data-v=\"14.3\">14.3</a>–<a class=\"vref\" href=\"capitulo-14.html#v4\" data-v=\"14.4\">14.4</a> lo explicará con una imagen: el gran <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, la naturaleza, es su matriz, en la que él deposita el germen, y él es «el padre que da la semilla». La segunda mitad del verso pasa del mundo al Veda: Kṛṣṇa es a la vez lo que hay que conocer y la palabra sagrada con que se lo conoce.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "yo-soy-el-rito-y-el-mundo"}, {"n": 18, "hablante": "krsna", "sa": ["गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् ।", "प्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् ॥१८॥"], "iast": ["gatir bhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt", "prabhavaḥ pralayaḥ sthānaṃ nidhānaṃ bījam avyayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy la meta, el que sustenta, el Señor, el <a class=\"t\" href=\"glosario.html#saksin\" data-t=\"saksin\">testigo</a>, la morada, el <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugio</a>, el amigo; el origen y la <a class=\"t\" href=\"glosario.html#pralaya\" data-t=\"pralaya\">disolución</a>, el fundamento, el tesoro, la <a class=\"t\" href=\"glosario.html#bija\" data-t=\"bija\">semilla</a> imperecedera.</span>", "palabras": [{"iast": "gatiḥ", "sa": "गतिः", "gram": "nom. sg. f.", "es": "la meta", "analisis": "√gam (ir): «el ir, adonde se va»"}, {"iast": "bhartā", "sa": "भर्ता", "gram": "nom. sg. m.", "es": "el que sustenta", "analisis": "√bhṛ (llevar, sustentar)"}, {"iast": "prabhuḥ", "sa": "प्रभुः", "gram": "nom. sg. m.", "es": "el Señor", "analisis": "pra + √bhū (tener poder)"}, {"iast": "sākṣī", "sa": "साक्षी", "gram": "nom. sg. m.", "es": "el testigo", "ref": "saksin", "analisis": "sa (con) + akṣa (ojo): «el que ve con sus ojos»"}, {"iast": "nivāsaḥ", "sa": "निवासः", "gram": "nom. sg. m.", "es": "la morada", "analisis": "ni + √vas (habitar)"}, {"iast": "śaraṇam", "sa": "शरणम्", "gram": "nom. sg. n.", "es": "el refugio", "ref": "prapatti"}, {"iast": "suhṛt", "sa": "सुहृत्", "gram": "nom. sg. m.", "es": "el amigo", "analisis": "su (buen) + hṛd (corazón): «el de buen corazón»"}, {"iast": "prabhavaḥ", "sa": "प्रभवः", "gram": "nom. sg. m.", "es": "el origen", "analisis": "pra + √bhū (surgir)"}, {"iast": "pralayaḥ", "sa": "प्रलयः", "gram": "nom. sg. m.", "es": "la disolución", "ref": "pralaya", "analisis": "pra + √lī (disolverse)"}, {"iast": "sthānam", "sa": "स्थानम्", "gram": "nom. sg. n.", "es": "el fundamento, el lugar donde todo permanece", "analisis": "√sthā (estar, permanecer)"}, {"iast": "nidhānam", "sa": "निधानम्", "gram": "nom. sg. n.", "es": "el tesoro, el depósito", "analisis": "ni + √dhā (depositar)"}, {"iast": "bījam", "sa": "बीजम्", "gram": "nom. sg. n.", "es": "la semilla", "ref": "bija"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "nom. sg. n. adj.", "es": "imperecedera"}], "nota": "<p>Doce nombres que van de lo más cercano a lo más vasto. <em>Sākṣin</em>, «el testigo», es el que ve con sus propios ojos sin intervenir (véase la ficha <a class=\"t\" href=\"glosario.html#saksin\" data-t=\"saksin\">sākṣin</a>). <em>Śaraṇa</em>, «el refugio», es la palabra de la llamada final de la obra: «refúgiate sólo en mí» (<a class=\"vref\" href=\"capitulo-18.html#v66\" data-v=\"18.66\">18.66</a>). <em>Suhṛd</em>, «el de buen corazón», el amigo, como en <a class=\"vref\" href=\"capitulo-05.html#v29\" data-v=\"5.29\">5.29</a>. <em>Nidhāna</em>, de ni-√dhā, «depositar», es el lugar donde se guarda algo, el depósito o el tesoro: aquello en que todo se recoge. La «semilla imperecedera» recuerda la «semilla eterna» de <a class=\"vref\" href=\"capitulo-07.html#v10\" data-v=\"7.10\">7.10</a>; <em>prabhava</em> y <em>pralaya</em>, origen y disolución, repiten <a class=\"vref\" href=\"capitulo-07.html#v6\" data-v=\"7.6\">7.6</a>.</p>", "interp": [{"titulo": "Una letanía", "html": "<p>Con este verso la serie se vuelve una letanía de nombres: lo que Kṛṣṇa es para quien se acerca a él (meta, sustento, refugio, amigo) se alterna con lo que es para el mundo (origen, disolución, fundamento, semilla). La devoción posterior hará de estas listas de nombres una forma de oración; el capítulo 11 pondrá en boca de Arjuna una letanía semejante (<a class=\"vref\" href=\"capitulo-11.html#v38\" data-v=\"11.38\">11.38</a>–<a class=\"vref\" href=\"capitulo-11.html#v40\" data-v=\"11.40\">11.40</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "yo-soy-el-rito-y-el-mundo"}, {"n": 19, "hablante": "krsna", "sa": ["तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च ।", "अमृतं चैव मृत्युश्च सदसच्चाहमर्जुन ॥१९॥"], "iast": ["tapāmy aham ahaṃ varṣaṃ nigṛhṇāmy utsṛjāmi ca", "amṛtaṃ caiva mṛtyuś ca sad asac cāham arjuna"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Yo doy calor; yo retengo la lluvia y la suelto. Soy la inmortalidad y también la muerte, el <a class=\"t\" href=\"glosario.html#sat-asat\" data-t=\"sat-asat\">ser y el no-ser</a>, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>.</span>", "palabras": [{"iast": "tapāmi", "sa": "तपामि", "gram": "1 sg. pres. act.", "es": "doy calor", "analisis": "√tap (calentar, arder)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "varṣam", "sa": "वर्षम्", "gram": "ac. sg. n.", "es": "la lluvia", "analisis": "√vṛṣ (llover)"}, {"iast": "nigṛhṇāmi", "sa": "निगृह्णामि", "gram": "1 sg. pres. act.", "es": "retengo", "analisis": "ni + √grah (sujetar, contener)"}, {"iast": "utsṛjāmi", "sa": "उत्सृजामि", "gram": "1 sg. pres. act.", "es": "suelto", "analisis": "ud + √sṛj (soltar, emitir)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "amṛtam", "sa": "अमृतम्", "gram": "nom. sg. n.", "es": "la inmortalidad", "analisis": "a (no) + mṛta (muerto)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también"}, {"iast": "mṛtyuḥ", "sa": "मृत्युः", "gram": "nom. sg. m.", "es": "la muerte", "analisis": "√mṛ (morir)"}, {"iast": "sat", "sa": "सत्", "gram": "nom. sg. n.", "es": "el ser, lo que es", "ref": "sat-asat", "analisis": "participio de √as (ser)"}, {"iast": "asat", "sa": "असत्", "gram": "nom. sg. n.", "es": "el no-ser, lo que no es", "ref": "sat-asat", "analisis": "a (no) + sat"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p>Kṛṣṇa habla aquí como el sol, que calienta y que, según la cosmología antigua, retiene el agua y la devuelve como lluvia. <em>Amṛta</em>, «lo no muerto», es la inmortalidad y también la bebida de los dioses; <em>mṛtyu</em>, la muerte. <em>Sad asat</em>: «el ser y el no-ser», o «lo que es y lo que no es»; la pareja abre la enseñanza filosófica de la obra (<a class=\"vref\" href=\"capitulo-02.html#v16\" data-v=\"2.16\">2.16</a>; véase la ficha <a class=\"t\" href=\"glosario.html#sat-asat\" data-t=\"sat-asat\">sat-asat</a>). Las lecturas difieren sobre qué es aquí el no-ser (véanse las alternativas).</p>", "interp": [{"titulo": "El sol que calienta y llueve", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la primera mitad desde el sol: hecho sol, Kṛṣṇa calienta el mundo con algunos de sus rayos, retiene la lluvia durante ocho meses y vuelve a soltarla en la estación de lluvias. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da la misma imagen y precisa los cuatro meses de lluvias.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Ser, no-ser y lo que está más allá", "html": "<p>El verso afirma que Kṛṣṇa es a la vez el ser y el no-ser. La Gītā dice también de brahman que «no se llama ser ni no-ser» (<a class=\"vref\" href=\"capitulo-13.html#v12\" data-v=\"13.12\">13.12</a>), y Arjuna, en la visión de la forma universal, dirá que Kṛṣṇa es «el ser, el no-ser y lo que está más allá de ambos» (<a class=\"vref\" href=\"capitulo-11.html#v37\" data-v=\"11.37\">11.37</a>). Las tres fórmulas no se contradicen: dicen, desde lados distintos, que ninguna de las dos categorías basta para nombrarlo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Yo doy calor; yo retengo la lluvia y la suelto. Soy la inmortalidad y también la muerte, lo manifiesto y lo no manifiesto, oh Arjuna.", "nota": "<p>Entendiendo <em>sat</em> como lo que se manifiesta, el efecto, y <em>asat</em> como lo no manifiesto, su causa; no se niega que lo segundo exista, sino que se pueda percibir. Es, con matices, la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que precisa que el Señor no es el no-ser absoluto y propone entender <em>sat</em> y <em>asat</em> como el efecto y la causa, y de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>: lo grosero, que se ve, y lo sutil, que no se ve. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> da, como su lectura principal, la del efecto y la causa.</p>"}, {"html": "Yo doy calor; yo retengo la lluvia y la suelto. Soy la inmortalidad y también la muerte, lo que existe ahora y lo que fue o será, oh Arjuna.", "nota": "<p>Así lo entiende <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: <em>sat</em> es lo que existe en el presente, y <em>asat</em>, lo que ya no existe o aún no existe; Kṛṣṇa abarca todos los estados de las cosas en el tiempo.</p>"}], "ens": "yo-soy-el-rito-y-el-mundo"}, {"n": 20, "hablante": "krsna", "sa": ["त्रैविद्या मां सोमपाः पूतपापा यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते ।", "ते पुण्यमासाद्य सुरेन्द्रलोकमश्नन्ति दिव्यान्दिवि देवभोगान् ॥२०॥"], "iast": ["trai-vidyā māṃ soma-pāḥ pūta-pāpā yajñair iṣṭvā svar-gatiṃ prārthayante", "te puṇyam āsādya surendra-lokam aśnanti divyān divi deva-bhogān"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los conocedores de los tres <a class=\"t\" href=\"glosario.html#trayi\" data-t=\"trayi\">Vedas</a>, que beben el <a class=\"t\" href=\"glosario.html#soma\" data-t=\"soma\">soma</a> y están limpios de <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>, tras ofrecerme <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a> piden ir al <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a>; y, llegados al mundo santo del <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">señor de los dioses</a>, gozan en el cielo de los placeres divinos de los dioses.</span>", "palabras": [{"iast": "trai-vidyāḥ", "sa": "त्रैविद्याः", "gram": "nom. pl. m.", "es": "los conocedores de los tres Vedas", "ref": "trayi", "analisis": "tri-vidyā (el triple saber, los tres Vedas), con alargamiento: «los que poseen el triple saber»"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "soma-pāḥ", "sa": "सोमपाः", "gram": "nom. pl. m.", "es": "los que beben el soma", "ref": "soma", "analisis": "soma + pā (que bebe)"}, {"iast": "pūta-pāpāḥ", "sa": "पूतपापाः", "gram": "nom. pl. m. comp.", "es": "limpios de pecado", "ref": "papa", "analisis": "pūta (purificado) + pāpa (pecado)"}, {"iast": "yajñaiḥ", "sa": "यज्ञैः", "gram": "instr. pl. m.", "es": "con sacrificios", "ref": "yajna"}, {"iast": "iṣṭvā", "sa": "इष्ट्वा", "gram": "abs.", "es": "habiendo ofrecido sacrificio", "analisis": "√yaj (sacrificar, adorar)"}, {"iast": "svar-gatim", "sa": "स्वर्गतिम्", "gram": "ac. sg. f.", "es": "la ida al cielo", "ref": "svarga", "analisis": "svar (el cielo) + gati (ida, camino)"}, {"iast": "prārthayante", "sa": "प्रार्थयन्ते", "gram": "3 pl. pres. med.", "es": "piden, ruegan", "analisis": "pra-√arth (pedir)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}, {"iast": "puṇyam", "sa": "पुण्यम्", "gram": "ac. sg. m.", "es": "santo, ganado por el mérito", "analisis": "puṇya (puro, santo; el mérito de las buenas obras)"}, {"iast": "āsādya", "sa": "आसाद्य", "gram": "abs.", "es": "habiendo alcanzado", "analisis": "ā-√sad (llegar a)"}, {"iast": "surendra-lokam", "sa": "सुरेन्द्रलोकम्", "gram": "ac. sg. m. comp.", "es": "el mundo del señor de los dioses", "ref": "indra", "analisis": "sura (dios) + indra (señor, jefe) + loka (mundo)"}, {"iast": "aśnanti", "sa": "अश्नन्ति", "gram": "3 pl. pres.", "es": "comen, disfrutan", "analisis": "√aś (comer, gozar)"}, {"iast": "divyān", "sa": "दिव्यान्", "gram": "ac. pl. m.", "es": "divinos, celestes"}, {"iast": "divi", "sa": "दिवि", "gram": "loc. sg.", "es": "en el cielo"}, {"iast": "deva-bhogān", "sa": "देवभोगान्", "gram": "ac. pl. m. comp.", "es": "los goces de los dioses", "ref": "deva", "analisis": "deva (dios) + bhoga (goce, disfrute)"}], "nota": "<p>Con 9.21, una estrofa larga, en <em>triṣṭubh</em>, como las de los ritos que describe. <em>Traividya</em> es el que posee el «triple saber», los tres Vedas del culto (véase <a class=\"t\" href=\"glosario.html#trayi\" data-t=\"trayi\">trayī</a>). El <em>soma</em> es la bebida sagrada que se exprime y se ofrece en los grandes sacrificios védicos; quienes la beben son los que los celebran. <em>Puṇya</em>, «santo», es la misma palabra que «mérito»: el mundo de Indra se alcanza por el mérito, y por eso se pierde cuando éste se agota (<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>). «Tras ofrecerme sacrificios»: el verso dice <em>mām</em>, «a mí», aunque esos sacrificios se dirijan a Indra y a los dioses del Veda; <a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>–<a class=\"vref\" href=\"capitulo-09.html#v24\" data-v=\"9.24\">9.24</a> explicarán por qué.</p>", "interp": [{"titulo": "El cielo del soma", "html": "<p>El verso recoge la promesa de la religión del sacrificio. Un himno del <em>Ṛg-veda</em> la formula así: «hemos bebido el soma, nos hemos vuelto inmortales, hemos llegado a la luz, hemos encontrado a los dioses» (8.48.3). La Gītā no niega que esa meta se alcance: dice que se alcanza, y que se goza, pero que es un mundo más, del que se vuelve. Es la crítica de <a class=\"vref\" href=\"capitulo-02.html#v42\" data-v=\"2.42\">2.42</a>–<a class=\"vref\" href=\"capitulo-02.html#v44\" data-v=\"2.44\">2.44</a> a los que «tienen el cielo por meta suprema», ahora en boca de Kṛṣṇa como una descripción serena.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "el-cielo-que-se-agota"}, {"n": 21, "hablante": "krsna", "sa": ["ते तं भुक्त्वा स्वर्गलोकं विशालं क्षीणे पुण्ये मर्त्यलोकं विशन्ति ।", "एवं त्रयीधर्ममनुप्रपन्ना गतागतं कामकामा लभन्ते ॥२१॥"], "iast": ["te taṃ bhuktvā svarga-lokaṃ viśālaṃ kṣīṇe puṇye martya-lokaṃ viśanti", "evaṃ trayī-dharmam anuprapannā gatāgataṃ kāma-kāmā labhante"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y, una vez que han disfrutado de ese vasto mundo celeste, agotado su mérito, entran en el mundo de los mortales. Así, los que siguen el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> de los tres <a class=\"t\" href=\"glosario.html#trayi\" data-t=\"trayi\">Vedas</a>, deseando lo que se desea, obtienen el ir y venir.</span>", "palabras": [{"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m.", "es": "ese"}, {"iast": "bhuktvā", "sa": "भुक्त्वा", "gram": "abs.", "es": "habiendo disfrutado", "analisis": "√bhuj (gozar, comer)"}, {"iast": "svarga-lokam", "sa": "स्वर्गलोकम्", "gram": "ac. sg. m. comp.", "es": "el mundo celeste", "ref": "svarga", "analisis": "svarga (cielo) + loka (mundo)"}, {"iast": "viśālam", "sa": "विशालम्", "gram": "ac. sg. m.", "es": "vasto, amplio"}, {"iast": "kṣīṇe", "sa": "क्षीणे", "gram": "loc. sg. n. (loc. abs.)", "es": "agotado", "analisis": "√kṣi (agotarse, consumirse)"}, {"iast": "puṇye", "sa": "पुण्ये", "gram": "loc. sg. n. (loc. abs.)", "es": "el mérito"}, {"iast": "martya-lokam", "sa": "मर्त्यलोकम्", "gram": "ac. sg. m. comp.", "es": "el mundo de los mortales", "analisis": "martya (mortal) + loka (mundo)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres.", "es": "entran", "analisis": "√viś (entrar)"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "trayī-dharmam", "sa": "त्रयीधर्मम्", "gram": "ac. sg. m. comp.", "es": "el dharma de los tres Vedas", "ref": "trayi", "analisis": "trayī (la tríada, los tres Vedas) + dharma (norma, deber)"}, {"iast": "anuprapannāḥ", "sa": "अनुप्रपन्नाः", "gram": "nom. pl. m. part.", "es": "los que siguen", "analisis": "anu-pra-√pad (seguir, acogerse a)"}, {"iast": "gatāgatam", "sa": "गतागतम्", "gram": "ac. sg. n. comp.", "es": "el ir y venir", "analisis": "gata (ido) + āgata (venido)"}, {"iast": "kāma-kāmāḥ", "sa": "कामकामाः", "gram": "nom. pl. m. comp.", "es": "los que desean lo deseable", "ref": "kama", "analisis": "kāma (objeto de deseo) + kāma (que desea): «deseosos de deseos»"}, {"iast": "labhante", "sa": "लभन्ते", "gram": "3 pl. pres. med.", "es": "obtienen", "analisis": "√labh (obtener)"}], "nota": "<p><em>Kṣīṇe puṇye</em>, «agotado el mérito»: el cielo es el fruto de unas obras, y dura lo que dura ese fruto. <em>Gatāgatam</em>, «lo ido y lo venido», es el vaivén de quien sube al cielo y vuelve a nacer, una y otra vez: lo mismo que <a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a> dijo de todos los mundos, «hasta el de Brahmā», y <a class=\"vref\" href=\"capitulo-08.html#v25\" data-v=\"8.25\">8.25</a> del que parte por el camino del humo. <em>Kāma-kāmāḥ</em>, «los que desean deseos», es un compuesto que repite la palabra para subrayarla: lo que buscan son objetos de deseo, y eso obtienen.</p>", "interp": [{"titulo": "Ir y venir", "html": "<p>La idea viene de las Upaniṣads. La <em>Chāndogya</em> (5.10) describe cómo los que han vivido de sacrificios y buenas obras suben por el camino del humo hasta la luna, permanecen allí mientras dura su mérito y vuelven a nacer; la <em>Muṇḍaka</em> (1.2.10) llama «necios» a los que tienen los sacrificios y las obras pías por lo mejor: gozan en lo alto del cielo y vuelven a entrar en este mundo, o en uno más bajo. La Gītā toma la doctrina (véase <a class=\"t\" href=\"glosario.html#devayana\" data-t=\"devayana\">devayāna</a>) y le da una salida: el verso siguiente ofrece otro camino a los que piensan sólo en Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "el-cielo-que-se-agota"}, {"n": 22, "hablante": "krsna", "sa": ["अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते ।", "तेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम् ॥२२॥"], "iast": ["ananyāś cintayanto māṃ ye janāḥ paryupāsate", "teṣāṃ nityābhiyuktānāṃ yoga-kṣemaṃ vahāmy aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A los que, sin pensar en ninguna otra cosa, me meditan y me adoran, a esos que están siempre unidos a mí, yo les <a class=\"t\" href=\"glosario.html#yoga-ksema\" data-t=\"yoga-ksema\">procuro lo que no tienen y les conservo lo que tienen</a>.</span>", "palabras": [{"iast": "ananyāḥ", "sa": "अनन्याः", "gram": "nom. pl. m.", "es": "sin otro (objeto), sin pensar en otra cosa", "analisis": "a-ananya: «que no tienen otro»"}, {"iast": "cintayantaḥ", "sa": "चिन्तयन्तः", "gram": "nom. pl. m. part. pres.", "es": "pensando, meditando", "analisis": "√cint (pensar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "en mí"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m.", "es": "los que"}, {"iast": "janāḥ", "sa": "जनाः", "gram": "nom. pl. m.", "es": "las personas, los hombres"}, {"iast": "paryupāsate", "sa": "पर्युपासते", "gram": "3 pl. pres. med.", "es": "adoran, veneran", "analisis": "pari-upa-√ās (sentarse junto a; servir, adorar)"}, {"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m.", "es": "de ellos"}, {"iast": "nityābhiyuktānām", "sa": "नित्याभियुक्तानाम्", "gram": "gen. pl. m. comp.", "es": "siempre unidos (a mí)", "analisis": "nitya (siempre) + abhiyukta (aplicado, entregado)"}, {"iast": "yoga-kṣemam", "sa": "योगक्षेमम्", "gram": "ac. sg. m. comp.", "es": "la adquisición y la conservación", "ref": "yoga-ksema", "analisis": "yoga (obtener lo que no se tiene) + kṣema (guardar lo que se tiene)"}, {"iast": "vahāmi", "sa": "वहामि", "gram": "1 sg. pres.", "es": "llevo, procuro", "analisis": "√vah (llevar, cargar)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}], "nota": "<p><em>Ananya</em>, «sin otro», describe a quienes no tienen otro objeto que Kṛṣṇa; es la devoción «exclusiva» de <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a>. <em>Yoga-kṣema</em>, «adquirir y conservar», es la fórmula de la preocupación por el sustento: procurarse lo que falta y guardar lo que se tiene. En <a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a> Kṛṣṇa pedía a Arjuna vivir «sin afán de adquirir ni de conservar»; aquí dice por qué puede pedirlo: ese afán lo lleva él. <em>Vahāmi</em> es «llevo», como se lleva una carga.</p>", "interp": [{"titulo": "Los que no se ocupan de sí", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, estos devotos exclusivos son los renunciantes que se saben uno con el Señor. Se pregunta por qué el verso les promete esto sólo a ellos, si el Señor procura también lo suyo a los demás devotos. Responde que los demás se afanan también ellos mismos por lo suyo, mientras que quienes no ven nada fuera de él no buscan nada para sí, ni en la vida ni en la muerte, y sólo se refugian en él: por eso es él quien se ocupa de ellos. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da la misma respuesta.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Alcanzarlo y no volver", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el verso en clave de la meta: el <em>yoga</em> que Kṛṣṇa procura es alcanzarlo a él, y el <em>kṣema</em>, no volver ya a nacer. Los devotos exclusivos no pueden sostenerse sin pensar en él, y él mismo se encarga de que lleguen.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El que lleva la carga", "html": "<p>Un relato devocional muy difundido en la India cuenta que un brahmán pobre, al copiar o comentar la Gītā, no pudo creer que el Señor «llevara» en persona la carga de sus devotos y tachó <em>vahāmi</em>. Ese día llegaron a su casa dos muchachos con provisiones; uno de ellos mostró en la espalda las marcas de unos arañazos: los que el brahmán había hecho al tachar la palabra. El relato lee <em>vahāmi</em> al pie de la letra. El verso, además, ha llegado a la vida corriente: es el lema de la compañía estatal de seguros de vida de la India.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "A los que, sin pensar en ninguna otra cosa, me meditan y me adoran, a esos que están siempre unidos a mí, yo les concedo alcanzarme y los guardo de volver a perderme.", "nota": "<p><em>Yoga-kṣema</em> es, en su sentido corriente, «adquirir y conservar», y así lo glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, y lo traducen esta edición y <a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>. Pero lo que se adquiere y se conserva puede ser el propio Kṛṣṇa: así <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien <em>yoga</em> es alcanzar a Kṛṣṇa y <em>kṣema</em>, no volver ya al ciclo de los nacimientos.</p>"}], "ens": "yo-me-hago-cargo"}, {"n": 23, "hablante": "krsna", "sa": ["येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयान्विताः ।", "तेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम् ॥२३॥"], "iast": ["ye 'py anya-devatā bhaktā yajante śraddhayānvitāḥ", "te 'pi mām eva kaunteya yajanty avidhi-pūrvakam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">También los <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devotos</a> de otras <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">divinidades</a> que les ofrecen sacrificios llenos de <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a>, a mí es a quien sacrifican, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, aunque no según la regla.</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m.", "es": "los que"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también, incluso"}, {"iast": "anya-devatāḥ", "sa": "अन्यदेवताः", "gram": "ac. pl. f. comp.", "es": "a otras divinidades", "ref": "deva", "analisis": "anya (otro) + devatā (divinidad)"}, {"iast": "bhaktāḥ", "sa": "भक्ताः", "gram": "nom. pl. m.", "es": "devotos", "ref": "bhakti"}, {"iast": "yajante", "sa": "यजन्ते", "gram": "3 pl. pres. med.", "es": "sacrifican, adoran", "analisis": "√yaj (sacrificar)"}, {"iast": "śraddhayā", "sa": "श्रद्धया", "gram": "instr. sg. f.", "es": "con fe", "ref": "sraddha"}, {"iast": "anvitāḥ", "sa": "अन्विताः", "gram": "nom. pl. m. part.", "es": "dotados, llenos", "analisis": "anu-√i (acompañar)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente, sólo"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "yajanti", "sa": "यजन्ति", "gram": "3 pl. pres. act.", "es": "sacrifican"}, {"iast": "avidhi-pūrvakam", "sa": "अविधिपूर्वकम्", "gram": "adv. comp.", "es": "no según la regla", "analisis": "a-vidhi (sin regla, sin norma) + pūrvaka (precedido de, conforme a)"}], "nota": "<p>Es la conclusión de lo que el capítulo 7 dijo del culto a otras divinidades (<a class=\"vref\" href=\"capitulo-07.html#v20\" data-v=\"7.20\">7.20</a>–<a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a>): Kṛṣṇa afianza esa fe y concede su fruto. Aquí da un paso más: ese culto llega a él, porque no hay otro destinatario de los sacrificios. La reserva está en <em>avidhi-pūrvakam</em>: no lo hacen como corresponde, y el verso siguiente dice cuál es la falta.</p>", "interp": [{"titulo": "Un mismo destinatario", "html": "<p>El verso cierra un arco que empezó en <a class=\"vref\" href=\"capitulo-04.html#v11\" data-v=\"4.11\">4.11</a>: «como se acercan a mí, así los acojo; los hombres siguen mi camino de todas maneras». Ni allí ni aquí Kṛṣṇa condena el culto a otros dioses; lo sitúa. Todo culto sincero se dirige, sépalo o no, a quien es el único que recibe los sacrificios.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "También los devotos de otras divinidades que les ofrecen sacrificios llenos de fe, a mí es a quien sacrifican, oh Kaunteya, aunque sin saberlo.", "nota": "<p><em>Avidhi-pūrvakam</em> es literalmente «no precedido de la regla». La traducción principal lo deja así, como <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>: no siguen la regla de las Upaniṣads, que enseña a adorar en esos dioses al Señor del que son cuerpo; esta alternativa sigue a <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y a <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que glosan <em>avidhi</em> como «ignorancia» (<em>ajñāna</em>): sacrifican a Kṛṣṇa sin saber que es él quien recibe el sacrificio, como dirá el verso siguiente.</p>"}], "ens": "todo-sacrificio-llega-a-el"}, {"n": 24, "hablante": "krsna", "sa": ["अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च ।", "न तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते ॥२४॥"], "iast": ["ahaṃ hi sarva-yajñānāṃ bhoktā ca prabhur eva ca", "na tu mām abhijānanti tattvenātaś cyavanti te"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque yo soy el que goza de todos los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a>, y también su señor; pero ellos no me conocen en verdad, y por eso caen.</span>", "palabras": [{"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "sarva-yajñānām", "sa": "सर्वयज्ञानाम्", "gram": "gen. pl. m. comp.", "es": "de todos los sacrificios", "ref": "yajna", "analisis": "sarva (todo) + yajña (sacrificio)"}, {"iast": "bhoktā", "sa": "भोक्ता", "gram": "nom. sg. m.", "es": "el que goza, el que disfruta", "analisis": "√bhuj (gozar)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "prabhuḥ", "sa": "प्रभुः", "gram": "nom. sg. m.", "es": "el señor"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también, ciertamente"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "abhijānanti", "sa": "अभिजानन्ति", "gram": "3 pl. pres.", "es": "conocen, reconocen", "analisis": "abhi-√jñā (reconocer)"}, {"iast": "tattvena", "sa": "तत्त्वेन", "gram": "instr. sg. n.", "es": "en verdad, tal como soy", "analisis": "tattva (la verdad, lo que algo es)"}, {"iast": "ataḥ", "sa": "अतः", "gram": "ind.", "es": "por eso"}, {"iast": "cyavanti", "sa": "च्यवन्ति", "gram": "3 pl. pres.", "es": "caen", "analisis": "√cyu (caer, apartarse)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m.", "es": "ellos"}], "nota": "<p>Es lo que <a class=\"vref\" href=\"capitulo-05.html#v29\" data-v=\"5.29\">5.29</a> ya enunció («el que disfruta de los sacrificios y las austeridades») y lo que <a class=\"vref\" href=\"capitulo-08.html#v4\" data-v=\"8.4\">8.4</a> llamó <em><a class=\"t\" href=\"glosario.html#adhiyajna\" data-t=\"adhiyajna\">adhiyajña</a></em>: Kṛṣṇa es a la vez el que recibe el sacrificio y el que dispone su fruto. <em>Cyavanti</em>, «caen», resume <a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>: no reconocer al verdadero destinatario lleva al ir y venir del cielo a la tierra.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "todo-sacrificio-llega-a-el"}, {"n": 25, "hablante": "krsna", "sa": ["यान्ति देवव्रता देवान्पितॄन्यान्ति पितृव्रताः ।", "भूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम् ॥२५॥"], "iast": ["yānti deva-vratā devān pitṝn yānti pitṛ-vratāḥ", "bhūtāni yānti bhūtejyā yānti mad-yājino 'pi mām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los consagrados a los <a class=\"t\" href=\"glosario.html#deva\" data-t=\"deva\">dioses</a> van a los dioses; a los <a class=\"t\" href=\"glosario.html#pitr\" data-t=\"pitr\">antepasados</a> van los consagrados a los antepasados; a los espíritus, los que sacrifican a los espíritus; y los que me sacrifican a mí vienen a mí.</span>", "palabras": [{"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres.", "es": "van", "analisis": "√yā (ir)"}, {"iast": "deva-vratāḥ", "sa": "देवव्रताः", "gram": "nom. pl. m. comp.", "es": "los consagrados a los dioses", "ref": "deva", "analisis": "deva (dios) + vrata (voto, observancia)"}, {"iast": "devān", "sa": "देवान्", "gram": "ac. pl. m.", "es": "a los dioses", "ref": "deva"}, {"iast": "pitṝn", "sa": "पितॄन्", "gram": "ac. pl. m.", "es": "a los antepasados", "ref": "pitr"}, {"iast": "pitṛ-vratāḥ", "sa": "पितृव्रताः", "gram": "nom. pl. m. comp.", "es": "los consagrados a los antepasados", "ref": "pitr", "analisis": "pitṛ (antepasado) + vrata (voto)"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "ac. pl. n.", "es": "a los espíritus"}, {"iast": "bhūtejyāḥ", "sa": "भूतेज्याः", "gram": "nom. pl. m. comp.", "es": "los que sacrifican a los espíritus", "analisis": "bhūta (espíritu, ser) + ijyā (sacrificio)"}, {"iast": "mad-yājinaḥ", "sa": "मद्याजिनः", "gram": "nom. pl. m. comp.", "es": "los que me sacrifican a mí", "analisis": "mad (a mí) + yājin (el que sacrifica)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}], "nota": "<p><em>Vrata</em> es el voto, la observancia: el «consagrado a los dioses» es quien les dedica su culto. <em>Bhūta</em> tiene aquí el sentido de «espíritus», los seres invisibles a los que se ofrecían cultos menores. La regla es la de <a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a> («los que sacrifican a los dioses van a los dioses; mis devotos vienen a mí»), desarrollada con dos casos más: los antepasados y los espíritus.</p>", "interp": [{"titulo": "Cada cual va a lo que adora", "html": "<p>El verso cierra la sección con una ley sencilla: el destino sigue al objeto del culto. Los dioses, los antepasados y los espíritus son destinos reales, pero, como el cielo de <a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>, forman parte de los mundos de los que se vuelve; sólo quien se dirige a Kṛṣṇa llega a lo que no pasa (<a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "todo-sacrificio-llega-a-el"}, {"n": 26, "hablante": "krsna", "sa": ["पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति ।", "तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः ॥२६॥"], "iast": ["patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati", "tad ahaṃ bhakty-upahṛtam aśnāmi prayatātmanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Una hoja, una flor, un fruto, agua: lo que alguien me ofrece con <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>, esa ofrenda hecha con devoción por quien tiene el ser purificado, yo la acepto.</span>", "palabras": [{"iast": "patram", "sa": "पत्रम्", "gram": "ac. sg. n.", "es": "una hoja"}, {"iast": "puṣpam", "sa": "पुष्पम्", "gram": "ac. sg. n.", "es": "una flor"}, {"iast": "phalam", "sa": "फलम्", "gram": "ac. sg. n.", "es": "un fruto"}, {"iast": "toyam", "sa": "तोयम्", "gram": "ac. sg. n.", "es": "agua"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}, {"iast": "bhaktyā", "sa": "भक्त्या", "gram": "instr. sg. f.", "es": "con devoción", "ref": "bhakti", "analisis": "bhakti (devoción; √bhaj, participar, adorar)"}, {"iast": "prayacchati", "sa": "प्रयच्छति", "gram": "3 sg. pres. act.", "es": "ofrece", "analisis": "pra-√yam (tender, ofrecer)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "bhakty-upahṛtam", "sa": "भक्त्युपहृतम्", "gram": "ac. sg. n. comp.", "es": "ofrecido con devoción", "ref": "bhakti", "analisis": "bhakti (devoción) + upahṛta (presentado, ofrecido; upa-√hṛ)"}, {"iast": "aśnāmi", "sa": "अश्नामि", "gram": "1 sg. pres. act.", "es": "como, tomo", "analisis": "√aś (comer, disfrutar)"}, {"iast": "prayatātmanaḥ", "sa": "प्रयतात्मनः", "gram": "gen. sg. m. comp.", "es": "del que tiene el ser purificado", "ref": "atman", "analisis": "prayata (contenido, purificado; pra-√yam) + ātman (el sí-mismo, el ánimo)"}], "nota": "<p><em>Aśnāmi</em>: literalmente «como», «tomo como alimento»; la traducción dice «acepto», como glosan <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> (<em>gṛhṇāmi</em>), porque la lista incluye una flor y agua, pero el verbo es el del comer: Kṛṣṇa no sólo recibe la ofrenda, la disfruta. <em>Bhakty-upahṛtam</em>: «presentado con devoción»; la palabra <em>bhakti</em> aparece dos veces en el verso, como para subrayar que la ofrenda vale por ella. Los cuatro objetos —hoja, flor, fruto, agua— son lo que cualquiera puede conseguir sin gasto, frente a los sacrificios costosos de <a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>.</p>", "interp": [{"titulo": "Lo más sencillo", "html": "<p>El capítulo ha hablado de los que ofrecen sacrificios védicos para alcanzar el cielo y vuelven cuando se agota su mérito (<a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>), y de los que adoran a otros dioses (<a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>). Frente a todo eso, Kṛṣṇa pide lo mínimo: una hoja, una flor, un fruto, un poco de agua. El acento no está en la cosa, sino en la devoción con que se da, que el verso nombra dos veces.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La ofrenda en el culto", "html": "<p>El verso describe lo que todavía se hace en los templos y en los altares domésticos de la India: se ofrecen a la imagen flores, hojas de tulasī, frutas y agua, y el alimento ofrecido se reparte después como <a class=\"t\" href=\"glosario.html#prasada\" data-t=\"prasada\">prasāda</a>, «gracia», el don que vuelve del dios. La tradición ve en este verso el fundamento de esa práctica.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}, {"titulo": "Lo que Kṛṣṇa pide", "html": "<p>Prabhupāda, en su comentario, subraya que Kṛṣṇa enumera alimentos vegetales —hojas, flores, frutos, agua— y concluye que el devoto no le ofrece carne, pescado ni huevos; por eso la cocina de los templos de su movimiento es vegetariana y todo se cocina para ofrecerlo antes de comerlo.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Una hoja, una flor, un fruto, agua: lo que alguien me ofrece con devoción, esa ofrenda hecha con devoción por quien se domina, yo la acepto.", "nota": "<p><em>Prayata</em>, participio de <em>pra-√yam</em>, «contener, sujetar», vale a la vez «dominado, contenido» y, en el lenguaje del culto, «puro, ritualmente preparado». La traducción principal toma el segundo sentido, el de la pureza; la alternativa, el primero, el del dominio de sí. En los dos casos lo que cuenta es la disposición del que ofrece, no el valor de la ofrenda.</p>"}], "ens": "ofrecerlo-todo"}, {"n": 27, "hablante": "krsna", "sa": ["यत्करोषि यदश्नासि यज्जुहोषि ददासि यत् ।", "यत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम् ॥२७॥"], "iast": ["yat karoṣi yad aśnāsi yaj juhoṣi dadāsi yat", "yat tapasyasi kaunteya tat kuruṣva mad-arpaṇam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo que hagas, lo que comas, lo que ofrezcas en sacrificio, lo que des, la <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridad</a> que practiques, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, hazlo como ofrenda a mí.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. pron.", "es": "lo que"}, {"iast": "karoṣi", "sa": "करोषि", "gram": "2 sg. pres. act.", "es": "haces", "ref": "karma", "analisis": "√kṛ (hacer)"}, {"iast": "aśnāsi", "sa": "अश्नासि", "gram": "2 sg. pres. act.", "es": "comes", "analisis": "√aś (comer)"}, {"iast": "juhoṣi", "sa": "जुहोषि", "gram": "2 sg. pres. act.", "es": "ofreces en el fuego", "ref": "yajna", "analisis": "√hu (verter en el fuego, sacrificar)"}, {"iast": "dadāsi", "sa": "ददासि", "gram": "2 sg. pres. act.", "es": "das", "analisis": "√dā (dar)"}, {"iast": "tapasyasi", "sa": "तपस्यसि", "gram": "2 sg. pres. act.", "es": "practicas austeridad", "ref": "tapas", "analisis": "denominativo de tapas (austeridad)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh hijo de Kuntī", "ref": "kaunteya"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "kuruṣva", "sa": "कुरुष्व", "gram": "2 sg. impv. med.", "es": "hazlo", "analisis": "√kṛ (hacer)"}, {"iast": "mad-arpaṇam", "sa": "मदर्पणम्", "gram": "ac. sg. n. comp.", "es": "como ofrenda a mí", "analisis": "mad (a mí) + arpaṇa (ofrenda, entrega; √ṛ en causativo, «poner en»)"}], "nota": "<p>La lista sigue un orden: toda acción (<em>karoṣi</em>), la más cotidiana (comer), y luego las tres obras religiosas que la Gītā agrupa a menudo, el sacrificio (<em>juhoṣi</em>, de √hu, «verter en el fuego»), el don (<em>dadāsi</em>) y la austeridad (<em>tapasyasi</em>); cf. <a class=\"vref\" href=\"capitulo-17.html#v7\" data-v=\"17.7\">17.7</a> y <a class=\"vref\" href=\"capitulo-18.html#v5\" data-v=\"18.5\">18.5</a>. <em>Mad-arpaṇam</em>: «como entrega a mí»; es la palabra de <a class=\"vref\" href=\"capitulo-04.html#v24\" data-v=\"4.24\">4.24</a>, <em>brahmārpaṇam</em>, «brahman es la ofrenda», ahora referida a Kṛṣṇa en persona.</p>", "interp": [{"titulo": "Toda la vida como ofrenda", "html": "<p>El verso generaliza el anterior: no sólo la hoja y la flor, sino todo lo que se hace puede ser ofrenda. Recoge así una línea que atraviesa la Gītā: actuar sin apego, como sacrificio (<a class=\"vref\" href=\"capitulo-03.html#v9\" data-v=\"3.9\">3.9</a>), «depositando en mí todas las acciones» (<a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>), actuar «depositando las acciones en brahman» (<a class=\"vref\" href=\"capitulo-05.html#v10\" data-v=\"5.10\">5.10</a>). Aquí la ofrenda se dirige expresamente a Kṛṣṇa, y la técnica de la acción desinteresada se convierte en devoción. Volverá con la misma fuerza en <a class=\"vref\" href=\"capitulo-12.html#v6\" data-v=\"12.6\">12.6</a> y <a class=\"vref\" href=\"capitulo-18.html#v57\" data-v=\"18.57\">18.57</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ofrecerlo-todo"}, {"n": 28, "hablante": "krsna", "sa": ["शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः ।", "संन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि ॥२८॥"], "iast": ["śubhāśubha-phalair evaṃ mokṣyase karma-bandhanaiḥ", "saṃnyāsa-yoga-yuktātmā vimukto mām upaiṣyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así te librarás de las ataduras de la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, de sus <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">frutos</a> buenos y malos; con el ser unido por el yoga de la <a class=\"t\" href=\"glosario.html#sannyasa\" data-t=\"sannyasa\">renuncia</a>, <a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">liberado</a>, vendrás a mí.</span>", "palabras": [{"iast": "śubha-aśubha-phalaiḥ", "sa": "शुभाशुभफलैः", "gram": "instr. pl. n. comp.", "es": "de frutos buenos y malos", "ref": "phala", "analisis": "śubha (bueno, propicio) + aśubha (malo) + phala (fruto)"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "mokṣyase", "sa": "मोक्ष्यसे", "gram": "2 sg. fut. med.", "es": "te librarás", "ref": "moksa", "analisis": "√muc (soltar, liberar)"}, {"iast": "karma-bandhanaiḥ", "sa": "कर्मबन्धनैः", "gram": "instr. pl. n. comp.", "es": "de las ataduras de la acción", "ref": "karma", "analisis": "karman (acción) + bandhana (atadura; √bandh, atar)"}, {"iast": "saṃnyāsa-yoga-yukta-ātmā", "sa": "संन्यासयोगयुक्तात्मा", "gram": "nom. sg. m. comp.", "es": "con el ser unido por el yoga de la renuncia", "ref": "sannyasa", "analisis": "saṃnyāsa (renuncia) + yoga + yukta (unido) + ātman (el sí-mismo, el ser)"}, {"iast": "vimuktaḥ", "sa": "विमुक्तः", "gram": "nom. sg. m. part.", "es": "liberado", "ref": "moksa", "analisis": "vi-√muc (soltar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "upaiṣyasi", "sa": "उपैष्यसि", "gram": "2 sg. fut. act.", "es": "vendrás", "analisis": "upa-√i (acercarse, llegar)"}], "nota": "<p><em>Śubhāśubha-phalaiḥ … karma-bandhanaiḥ</em>: «de las ataduras de la acción, que tienen frutos buenos y malos»; también los frutos buenos atan, porque obligan a volver para disfrutarlos (<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>). <em>Saṃnyāsa-yoga</em>: «el yoga de la renuncia»; por el contexto, la renuncia de la que habla no es abandonar las acciones, sino la ofrenda del verso anterior, que entrega a Kṛṣṇa la acción y su fruto, como en <a class=\"vref\" href=\"capitulo-05.html#v1\" data-v=\"5.1\">5.1</a>–<a class=\"vref\" href=\"capitulo-05.html#v6\" data-v=\"5.6\">5.6</a> y en <a class=\"vref\" href=\"capitulo-06.html#v1\" data-v=\"6.1\">6.1</a>.</p>", "interp": [{"titulo": "Renuncia que es yoga", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica el compuesto así: la ofrenda de todo a Kṛṣṇa es renuncia, y a la vez es yoga porque sigue siendo acción; quien tiene la mente unida por esa disciplina, libre en vida de las ataduras de la acción, llega a Kṛṣṇa cuando cae el cuerpo. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden también la renuncia como la ofrenda de las acciones; Madhusūdana la llama yoga porque purifica la mente.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ofrecerlo-todo"}, {"n": 29, "hablante": "krsna", "sa": ["समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः ।", "ये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम् ॥२९॥"], "iast": ["samo 'haṃ sarva-bhūteṣu na me dveṣyo 'sti na priyaḥ", "ye bhajanti tu māṃ bhaktyā mayi te teṣu cāpy aham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Soy el mismo para todos los seres: no hay nadie a quien odie ni nadie a quien prefiera. Pero los que me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adoran</a> con devoción están en mí, y yo también en ellos.</span>", "palabras": [{"iast": "samaḥ", "sa": "समः", "gram": "nom. sg. m.", "es": "igual, el mismo", "ref": "samatva", "analisis": "sama (igual, ecuánime)"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "sarva-bhūteṣu", "sa": "सर्वभूतेषु", "gram": "loc. pl. n. comp.", "es": "para todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "para mí"}, {"iast": "dveṣyaḥ", "sa": "द्वेष्यः", "gram": "nom. sg. m. gerundivo", "es": "odioso", "analisis": "√dviṣ (odiar)"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m.", "es": "querido"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron.", "es": "los que"}, {"iast": "bhajanti", "sa": "भजन्ति", "gram": "3 pl. pres. act.", "es": "adoran", "ref": "bhakti", "analisis": "√bhaj (participar, adorar)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "bhaktyā", "sa": "भक्त्या", "gram": "instr. sg. f.", "es": "con devoción", "ref": "bhakti"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. m. pron.", "es": "en ellos"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}], "nota": "<p><em>Samaḥ</em>: «igual», el mismo para todos, como el sabio ecuánime de <a class=\"vref\" href=\"capitulo-06.html#v9\" data-v=\"6.9\">6.9</a>. <em>Na me dveṣyo &#x27;sti na priyaḥ</em>: literalmente «no hay para mí ni odioso ni querido»; la traducción dice «a quien prefiera» porque el verso no niega que Kṛṣṇa ame —en <a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a> el sabio le es «sobremanera querido»—, sino que haga acepción de personas. La segunda mitad no contradice la primera: la diferencia no la pone Kṛṣṇa, sino la respuesta de cada uno.</p>", "interp": [{"titulo": "Como el fuego", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica la aparente contradicción con una imagen: Kṛṣṇa es como el fuego, que no quita el frío a los que están lejos, pero sí a los que se acercan. No es parcialidad del fuego: del mismo modo, Kṛṣṇa favorece a los devotos y no a los demás sin odiar a nadie, y los devotos están en él, y él en ellos, por su naturaleza misma, no por una preferencia suya. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> usa también la imagen del fuego, junto a la del árbol de los deseos; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> prefiere la luz del sol, que sólo se refleja en un espejo limpio, y recuerda también el fuego y el árbol.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sin distinción de nacimiento", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende que, para Kṛṣṇa, nadie es despreciable ni preferido por su nacimiento, su forma, su naturaleza o su saber: lo que cuenta es la devoción; y los que lo adoran viven en él como si fueran sus iguales, y él en ellos como si fueran superiores a él. Es la lectura que prepara los versos siguientes, donde se abre el camino al de peor conducta y a los de origen pecaminoso.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Soy el mismo para todos los seres: no hay nadie a quien odie ni nadie a quien prefiera. Pero los que me adoran con devoción permanecen en mí, y yo me manifiesto en ellos.", "nota": "<p>La segunda mitad dice sólo «en mí ellos, y en ellos también yo», sin verbo. La traducción principal suple «están»; la alternativa entiende una relación distinta en cada dirección: el devoto vive en Kṛṣṇa, y Kṛṣṇa se hace presente o se revela en el devoto. Es una de las maneras de explicar cómo Kṛṣṇa, presente en todo (<a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a>), puede estar «en» unos de un modo especial.</p>"}], "ens": "mi-devoto-no-perece"}, {"n": 30, "hablante": "krsna", "sa": ["अपि चेत्सुदुराचारो भजते मामनन्यभाक् ।", "साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥३०॥"], "iast": ["api cet sudurācāro bhajate mām ananya-bhāk", "sādhur eva sa mantavyaḥ samyag vyavasito hi saḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aunque alguien de muy mala conducta me <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adore</a> sin adorar a ningún otro, ha de ser tenido por bueno, pues ha tomado la resolución recta.</span>", "palabras": [{"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "cet", "sa": "चेत्", "gram": "ind.", "es": "si"}, {"iast": "su-durācāraḥ", "sa": "सुदुराचारः", "gram": "nom. sg. m. comp.", "es": "de muy mala conducta", "analisis": "su (muy) + dur (mal) + ācāra (conducta)"}, {"iast": "bhajate", "sa": "भजते", "gram": "3 sg. pres. med.", "es": "adora", "ref": "bhakti", "analisis": "√bhaj (adorar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "ananya-bhāk", "sa": "अनन्यभाक्", "gram": "nom. sg. m. comp.", "es": "sin adorar a otro", "analisis": "ananya (no otro) + bhāj (que participa, que adora; √bhaj)"}, {"iast": "sādhuḥ", "sa": "साधुः", "gram": "nom. sg. m.", "es": "bueno, recto"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sin duda"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "él"}, {"iast": "mantavyaḥ", "sa": "मन्तव्यः", "gram": "nom. sg. m. gerundivo", "es": "ha de ser tenido por", "analisis": "√man (pensar, considerar)"}, {"iast": "samyak", "sa": "सम्यक्", "gram": "ind.", "es": "rectamente"}, {"iast": "vyavasitaḥ", "sa": "व्यवसितः", "gram": "nom. sg. m. part.", "es": "ha resuelto", "analisis": "vi-ava-√so (decidir, resolverse)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}], "nota": "<p><em>Ananya-bhāk</em>: «el que no adora a otro», que no reparte su devoción; cf. <em>ananya-bhakti</em> en <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a> y <a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>. <em>Samyag vyavasitaḥ</em>: «rectamente resuelto», el que ha tomado la decisión correcta; es el lenguaje del entendimiento «resuelto» (<em>vyavasāyātmikā buddhi</em>) de <a class=\"vref\" href=\"capitulo-02.html#v41\" data-v=\"2.41\">2.41</a>.</p>", "interp": [{"titulo": "La resolución, no el pasado", "html": "<p>El verso es uno de los más audaces de la Gītā: ni el de peor conducta queda excluido. Pero no dice que la conducta no importe: el fundamento que da es la resolución («ha resuelto rectamente»), y el verso siguiente añade la consecuencia, que «pronto se vuelve recto». La devoción no se presenta como una excusa, sino como el comienzo de una transformación.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Incluso si quien me adora sin adorar a ningún otro hubiera llevado una vida de muy mala conducta, ha de ser tenido por bueno, pues ha tomado la resolución recta.", "nota": "<p>El verso no dice si la mala conducta es pasada o continúa. La traducción principal deja abierto el tiempo; la alternativa la sitúa en el pasado, como sugiere el verso siguiente, según el cual el que así adora «pronto se vuelve recto» (<a class=\"vref\" href=\"capitulo-09.html#v31\" data-v=\"9.31\">9.31</a>); así <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> («aunque antes no fuera bueno») y <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, para quien deja la mala conducta exterior por la fuerza de su recta resolución interior, mientras que <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> admite que sus faltas de conducta continúen: lo que hace bueno al que obraba mal no es una absolución de su conducta, sino el cambio que empieza con la resolución. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, admite que la falta persista: es una pequeña deficiencia que no le quita al devoto su valor, y que la devoción irá eliminando.</p>"}], "ens": "mi-devoto-no-perece"}, {"n": 31, "hablante": "krsna", "sa": ["क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति ।", "कौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति ॥३१॥"], "iast": ["kṣipraṃ bhavati dharmātmā śaśvac-chāntiṃ nigacchati", "kaunteya pratijānīhi na me bhaktaḥ praṇaśyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pronto se vuelve recto y alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> eterna. Proclámalo, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>: mi devoto no perece.</span>", "palabras": [{"iast": "kṣipram", "sa": "क्षिप्रम्", "gram": "ind.", "es": "pronto"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "se vuelve", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "dharma-ātmā", "sa": "धर्मात्मा", "gram": "nom. sg. m. comp.", "es": "de alma recta", "ref": "dharma", "analisis": "dharma + ātman (ánimo, ser)"}, {"iast": "śaśvat", "sa": "शश्वत्", "gram": "ind.", "es": "eterna, perpetua"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi", "analisis": "√śam (calmarse)"}, {"iast": "nigacchati", "sa": "निगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "ni-√gam (llegar)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh hijo de Kuntī", "ref": "kaunteya"}, {"iast": "pratijānīhi", "sa": "प्रतिजानीहि", "gram": "2 sg. impv. act.", "es": "sábelo con certeza; proclámalo", "analisis": "prati-√jñā (reconocer; asegurar, prometer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "bhaktaḥ", "sa": "भक्तः", "gram": "nom. sg. m.", "es": "devoto", "ref": "bhakti", "analisis": "√bhaj (adorar)"}, {"iast": "praṇaśyati", "sa": "प्रणश्यति", "gram": "3 sg. pres. act.", "es": "perece", "analisis": "pra-√naś (perderse, perecer)"}], "nota": "<p><em>Dharmātmā</em>: «de alma conforme al dharma», recto. <em>Śaśvac-chāntim</em>: «la paz perpetua», la de <a class=\"vref\" href=\"capitulo-02.html#v71\" data-v=\"2.71\">2.71</a> y <a class=\"vref\" href=\"capitulo-05.html#v29\" data-v=\"5.29\">5.29</a>. <em>Na me bhaktaḥ praṇaśyati</em>: «mi devoto no se pierde»; es la misma seguridad que Kṛṣṇa dio al yogui que no llega a la meta: «no hay perdición para él» (<a class=\"vref\" href=\"capitulo-06.html#v40\" data-v=\"6.40\">6.40</a>).</p>", "interp": [{"titulo": "Por qué lo proclama Arjuna", "html": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> se pregunta por qué Kṛṣṇa pide a Arjuna que lo proclame, en lugar de prometerlo él. Viśvanātha Cakravartī responde que Kṛṣṇa está dispuesto a faltar a su propia palabra por sus devotos —como cuando, habiendo prometido no combatir, tomó una rueda de carro contra Bhīṣma—, pero no deja que falle la palabra de un devoto; por eso pone la promesa en boca de Arjuna.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Pronto se vuelve recto y alcanza la paz eterna. Sábelo con certeza, oh Kaunteya: mi devoto no perece.", "nota": "<p><em>Pratijānīhi</em>, de <em>prati-√jñā</em>, puede ser «asegura, declara solemnemente, promete» o «reconoce, ten por cierto». La traducción principal toma el primer sentido, el de los comentaristas: Kṛṣṇa pide a Arjuna que sea él quien lo proclame. Es la lectura de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> («haz una promesa firme»), <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; Śrīdhara imagina a Arjuna proclamándolo, con el brazo en alto, ante una asamblea de disputadores. La alternativa toma el segundo sentido.</p>"}], "ens": "mi-devoto-no-perece"}, {"n": 32, "hablante": "krsna", "sa": ["मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः ।", "स्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम् ॥३२॥"], "iast": ["māṃ hi pārtha vyapāśritya ye 'pi syuḥ pāpa-yonayaḥ", "striyo vaiśyās tathā śūdrās te 'pi yānti parāṃ gatim"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque los que se <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugian</a> en mí, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, aunque sean de <a class=\"t\" href=\"glosario.html#papa-yoni\" data-t=\"papa-yoni\">origen pecaminoso</a>, mujeres, <a class=\"t\" href=\"glosario.html#vaisya\" data-t=\"vaisya\">vaiśyas</a> y también <a class=\"t\" href=\"glosario.html#sudra\" data-t=\"sudra\">śūdras</a>, también ellos alcanzan la meta suprema.</span>", "palabras": [{"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "en mí"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "porque"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh hijo de Pṛthā", "ref": "partha"}, {"iast": "vyapāśritya", "sa": "व्यपाश्रित्य", "gram": "abs.", "es": "refugiándose", "ref": "prapatti", "analisis": "vi-apa-ā-√śri (apoyarse, acogerse)"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron.", "es": "los que"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "syuḥ", "sa": "स्युः", "gram": "3 pl. opt. act.", "es": "sean", "analisis": "√as (ser)"}, {"iast": "pāpa-yonayaḥ", "sa": "पापयोनयः", "gram": "nom. pl. m. comp.", "es": "de origen pecaminoso", "ref": "papa-yoni", "analisis": "pāpa (pecado, mal) + yoni (matriz, origen)"}, {"iast": "striyaḥ", "sa": "स्त्रियः", "gram": "nom. pl. f.", "es": "las mujeres"}, {"iast": "vaiśyāḥ", "sa": "वैश्याः", "gram": "nom. pl. m.", "es": "los vaiśyas", "ref": "vaisya"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "y también"}, {"iast": "śūdrāḥ", "sa": "शूद्राः", "gram": "nom. pl. m.", "es": "los śūdras", "ref": "sudra"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van, alcanzan", "analisis": "√yā (ir)"}, {"iast": "parām", "sa": "पराम्", "gram": "ac. sg. f.", "es": "suprema"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "la meta", "analisis": "gati (ida, meta; √gam)"}], "nota": "<p><em>Pāpa-yonayaḥ</em>: literalmente «los de matriz pecaminosa», es decir, nacidos en una condición baja por efecto de sus acciones en vidas anteriores (véase la ficha). La enumeración que sigue no lleva conjunción con lo anterior, y de ahí las dos lecturas que se recogen como alternativas. Lo que el verso afirma sin ambigüedad es la conclusión: «también ellos» (<em>te &#x27;pi</em>) alcanzan la meta suprema. <em>Vyapāśritya</em>: «apoyándose, acogiéndose», un compuesto más intenso que el <em>prapadyante</em> de <a class=\"vref\" href=\"capitulo-07.html#v14\" data-v=\"7.14\">7.14</a>.</p>", "interp": [{"titulo": "Los excluidos del Veda", "html": "<p>Lo que tienen en común los grupos nombrados es su relación con el Veda. Según los tratados de dharma, las mujeres y los śūdras no recibían la iniciación (<em>upanayana</em>) ni podían estudiar el Veda ni celebrar por sí mismos sus ritos; los «de origen pecaminoso», si se leen como grupo aparte (así <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que piensan en los nacidos fuera de las cuatro clases), ni siquiera entraban en ese orden; para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> son las mismas mujeres, vaiśyas y śūdras. Los vaiśyas sí eran «nacidos dos veces» (<a class=\"t\" href=\"glosario.html#dvija\" data-t=\"dvija\">dvija</a>) y tenían acceso al Veda, y su presencia en la lista ha dado que pensar: <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> precisan que se trata de los vaiśyas dados sólo a la agricultura y oficios semejantes, y Dhanapati, que comenta a <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, los tiene por brahmanes o kṣatriyas de una vida anterior caídos por sus pecados. En ese marco, el verso dice que la vía que el capítulo enseña, la devoción, no requiere la condición que el Veda exigía: basta con refugiarse en Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Apertura y jerarquía", "html": "<p>El verso es a la vez una apertura y un testimonio de su tiempo. Abre la meta suprema a quienes el orden védico dejaba fuera, y ha sido leído como una de las afirmaciones más igualitarias de la tradición; pero lo hace dentro de una jerarquía que no discute: los califica de «origen pecaminoso», o al menos los nombra junto a ellos, y el verso siguiente añade «¡cuánto más los brahmanes!» (<a class=\"vref\" href=\"capitulo-09.html#v33\" data-v=\"9.33\">9.33</a>). Ni la lectura que lo convierte en una proclama moderna de igualdad ni la que sólo ve en él desprecio dan cuenta de las dos cosas a la vez.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Porque los que se refugian en mí, oh Pārtha, aunque sean de origen pecaminoso, como las mujeres, los vaiśyas y los śūdras, también ellos alcanzan la meta suprema.", "nota": "<p>Leyendo «mujeres, vaiśyas y śūdras» como aposición: serían los ejemplos de «los de origen pecaminoso». Es la construcción más inmediata si las dos mitades del verso se leen de corrido, y la de <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, que glosa <em>pāpa-yonayaḥ</em> como «de nacimiento pecaminoso» y sigue: «¿quiénes son? Lo dice: las mujeres, los vaiśyas y los śūdras». Así lo lee también <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como explica Vedānta Deśika.</p>"}, {"html": "Porque los que se refugian en mí, oh Pārtha, tanto los que sean de origen pecaminoso como las mujeres, los vaiśyas y los śūdras, también ellos alcanzan la meta suprema.", "nota": "<p>Leyendo dos grupos distintos: por un lado los «de origen pecaminoso», y por otro mujeres, vaiśyas y śūdras. Así <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, para quienes los primeros son los nacidos fuera de las clases (<em>antyaja</em>; Madhusūdana añade: o los animales), y Viśvanātha Cakravartī, que piensa en parias y extranjeros (<em>mleccha</em>). El sánscrito no tiene conjunción entre los dos miembros y admite las dos construcciones; la traducción principal conserva esa ambigüedad.</p>"}], "ens": "mi-devoto-no-perece"}, {"n": 33, "hablante": "krsna", "sa": ["किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा ।", "अनित्यमसुखं लोकमिमं प्राप्य भजस्व माम् ॥३३॥"], "iast": ["kiṃ punar brāhmaṇāḥ puṇyā bhaktā rājarṣayas tathā", "anityam asukhaṃ lokam imaṃ prāpya bhajasva mām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">¡Cuánto más los <a class=\"t\" href=\"glosario.html#brahmana\" data-t=\"brahmana\">brahmanes</a> de vida pura y los devotos <a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">reyes sabios</a>! Tú, que has llegado a este mundo pasajero y sin <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">dicha</a>, <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">adórame</a>.</span>", "palabras": [{"iast": "kim", "sa": "किम्", "gram": "ind.", "es": "cuánto"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "ind.", "es": "más"}, {"iast": "brāhmaṇāḥ", "sa": "ब्राह्मणाः", "gram": "nom. pl. m.", "es": "los brahmanes", "ref": "brahmana"}, {"iast": "puṇyāḥ", "sa": "पुण्याः", "gram": "nom. pl. m.", "es": "puros, meritorios"}, {"iast": "bhaktāḥ", "sa": "भक्ताः", "gram": "nom. pl. m.", "es": "devotos", "ref": "bhakti"}, {"iast": "rāja-ṛṣayaḥ", "sa": "राजर्षयः", "gram": "nom. pl. m. comp.", "es": "los reyes sabios", "ref": "rajarsi", "analisis": "rājan (rey) + ṛṣi (vidente)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "y también"}, {"iast": "anityam", "sa": "अनित्यम्", "gram": "ac. sg. m.", "es": "pasajero", "analisis": "a (no) + nitya (permanente)"}, {"iast": "asukham", "sa": "असुखम्", "gram": "ac. sg. m.", "es": "sin dicha", "ref": "sukha", "analisis": "a (no) + sukha (dicha)"}, {"iast": "lokam", "sa": "लोकम्", "gram": "ac. sg. m.", "es": "mundo"}, {"iast": "imam", "sa": "इमम्", "gram": "ac. sg. m. pron.", "es": "este"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "habiendo llegado a", "analisis": "pra-√āp (alcanzar)"}, {"iast": "bhajasva", "sa": "भजस्व", "gram": "2 sg. impv. med.", "es": "adora", "ref": "bhakti", "analisis": "√bhaj (adorar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}], "nota": "<p><em>Kiṃ punaḥ</em>: «¡cuánto más!», argumento <em>a fortiori</em>: si los excluidos alcanzan la meta, con más razón quienes tienen todas las condiciones. Los dos adjetivos pueden repartirse entre los dos grupos: <em>puṇyāḥ</em>, «puros, meritorios», va con los brahmanes (para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, «de nacimiento santo», frente a los «de origen pecaminoso» de <a class=\"vref\" href=\"capitulo-09.html#v32\" data-v=\"9.32\">9.32</a>); <em>bhaktāḥ</em>, «devotos», con los reyes sabios (<a class=\"t\" href=\"glosario.html#rajarsi\" data-t=\"rajarsi\">rājarṣi</a>, <a class=\"vref\" href=\"capitulo-04.html#v2\" data-v=\"4.2\">4.2</a>), entre los que se cuenta Arjuna. Pero <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> hacen devotos a unos y a otros. <em>Anityam asukhaṃ lokam</em>: «este mundo, pasajero y sin dicha»; la expresión resume el juicio del capítulo 8 sobre el renacimiento, «morada del dolor, pasajera» (<a class=\"vref\" href=\"capitulo-08.html#v15\" data-v=\"8.15\">8.15</a>).</p>", "interp": [{"titulo": "La conclusión para Arjuna", "html": "<p>El verso se vuelve al final hacia Arjuna, que es kṣatriya y, por su linaje, uno de esos «reyes sabios»: si la devoción abre la meta a todos, él no tiene ninguna excusa. El imperativo <em>bhajasva</em>, «adórame», cierra el argumento y prepara el verso final.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "mi-devoto-no-perece"}, {"n": 34, "hablante": "krsna", "sa": ["मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।", "मामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः ॥३४॥"], "iast": ["man-manā bhava mad-bhakto mad-yājī māṃ namaskuru", "mām evaiṣyasi yuktvaivam ātmānaṃ mat-parāyaṇaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Ten la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> en mí, sé mi devoto, ofréceme sacrificio, inclínate ante mí: así, unido a mí y teniéndome por meta suprema, vendrás a mí.</span>", "palabras": [{"iast": "man-manāḥ", "sa": "मन्मनाः", "gram": "nom. sg. m. comp.", "es": "con la mente en mí", "ref": "manas", "analisis": "mad (en mí) + manas (mente)"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. impv. act.", "es": "sé", "analisis": "√bhū (ser)"}, {"iast": "mad-bhaktaḥ", "sa": "मद्भक्तः", "gram": "nom. sg. m. comp.", "es": "devoto mío", "ref": "bhakti", "analisis": "mad (de mí) + bhakta (devoto)"}, {"iast": "mad-yājī", "sa": "मद्याजी", "gram": "nom. sg. m. comp.", "es": "el que me ofrece sacrificio", "ref": "yajna", "analisis": "mad (a mí) + yājin (el que sacrifica; √yaj)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "namaskuru", "sa": "नमस्कुरु", "gram": "2 sg. impv. act.", "es": "inclínate ante", "analisis": "namas (reverencia) + √kṛ (hacer)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "eṣyasi", "sa": "एष्यसि", "gram": "2 sg. fut. act.", "es": "vendrás", "analisis": "√i (ir)"}, {"iast": "yuktvā", "sa": "युक्त्वा", "gram": "abs.", "es": "habiendo unido", "ref": "yukta", "analisis": "√yuj (uncir, unir)"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "ātmānam", "sa": "आत्मानम्", "gram": "ac. sg. m.", "es": "a ti mismo", "ref": "atman"}, {"iast": "mat-parāyaṇaḥ", "sa": "मत्परायणः", "gram": "nom. sg. m. comp.", "es": "teniéndome por meta suprema", "analisis": "mad (yo) + parāyaṇa (meta suprema, refugio)"}], "nota": "<p>Cuatro imperativos breves: la mente (<em>man-manāḥ</em>), la devoción (<em>mad-bhaktaḥ</em>), el culto (<em>mad-yājī</em>) y la reverencia (<em>namaskuru</em>). <em>Yuktvaivam ātmānam</em>: «habiéndote unido así a ti mismo», es decir, habiéndote concentrado así; la traducción dice «unido a mí» porque el término de la unión es Kṛṣṇa, como indica <em>mat-parāyaṇaḥ</em>. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entienden <em>ātmānam</em> como la mente; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, en cambio, lo une a <em>mām</em>: «vendrás a mí, que soy así el sí-mismo» de todos los seres. La primera mitad del verso vuelve a la letra en <a class=\"vref\" href=\"capitulo-18.html#v65\" data-v=\"18.65\">18.65</a>, y también el comienzo de la segunda (<em>mām evaiṣyasi</em>), donde Kṛṣṇa la presenta como su enseñanza más secreta.</p>", "interp": [{"titulo": "El final del capítulo", "html": "<p>El capítulo empezó prometiendo «el saber más secreto» (<a class=\"vref\" href=\"capitulo-09.html#v1\" data-v=\"9.1\">9.1</a>–<a class=\"vref\" href=\"capitulo-09.html#v2\" data-v=\"9.2\">9.2</a>) y termina reduciéndolo a cuatro gestos que cualquiera puede hacer: pensar en Kṛṣṇa, amarlo, ofrecerle y saludarlo. La misma fórmula cerrará casi toda la Gītā en <a class=\"vref\" href=\"capitulo-18.html#v65\" data-v=\"18.65\">18.65</a>, seguida de la entrega total de <a class=\"vref\" href=\"capitulo-18.html#v66\" data-v=\"18.66\">18.66</a>.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La forma de la devoción", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el verso como la definición de la devoción que el capítulo ha ido describiendo: un pensamiento de Kṛṣṇa continuo, como un chorro de aceite que no se corta, movido por el amor a él como lo más querido, del que nacen el culto y la reverencia; quien así se une a él lo alcanza.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ten-la-mente-en-mi"}], "ensenanzas": [{"id": "como-el-viento-en-el-espacio", "desde": 4, "hasta": 6, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Todo está en él, y él no está en nada: el viento en el espacio", "resumen": "<p>Kṛṣṇa penetra todo el mundo con su forma no manifiesta: los seres están en él, pero él no está en ellos; y, llevando la paradoja más lejos, ni siquiera ellos están en él. A ese misterio lo llama su «yoga soberano». La imagen que lo aclara es la del viento, que se mueve por todas partes dentro del espacio sin que el espacio se mueva ni quede tocado. Retoma y amplía <a class=\"vref\" href=\"capitulo-07.html#v12\" data-v=\"7.12\">7.12</a>.</p>"}, {"id": "emite-sin-quedar-atado", "desde": 7, "hasta": 10, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El Señor que emite el mundo sin quedar atado", "resumen": "<p>Al final de cada <a class=\"t\" href=\"glosario.html#kalpa\" data-t=\"kalpa\">kalpa</a> los seres entran en la naturaleza de Kṛṣṇa, y al comienzo del siguiente él los emite de nuevo (<a class=\"vref\" href=\"capitulo-09.html#v7\" data-v=\"9.7\">9.7</a>–<a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a>). Pero esa actividad inmensa no lo ata: permanece «como indiferente», sin apego (<a class=\"vref\" href=\"capitulo-09.html#v9\" data-v=\"9.9\">9.9</a>); es la naturaleza la que, bajo su supervisión, engendra lo móvil y lo inmóvil (<a class=\"vref\" href=\"capitulo-09.html#v10\" data-v=\"9.10\">9.10</a>). Es la versión cósmica de lo que pide al yogui —obrar sin apego— y de lo que ya había dicho de sí: autor de las cuatro clases, pero no agente (<a class=\"vref\" href=\"capitulo-04.html#v13\" data-v=\"4.13\">4.13</a>–<a class=\"vref\" href=\"capitulo-04.html#v14\" data-v=\"4.14\">4.14</a>).</p>"}, {"id": "despreciado-en-forma-humana", "desde": 11, "hasta": 12, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Los que lo desprecian en forma humana", "resumen": "<p>Los necios ven a Kṛṣṇa en un cuerpo humano y lo desprecian, porque no conocen su estado supremo de gran Señor de los seres (<a class=\"vref\" href=\"capitulo-09.html#v11\" data-v=\"9.11\">9.11</a>); sus esperanzas, sus obras y su conocimiento son vanos, y se acogen a una naturaleza que extravía (<a class=\"vref\" href=\"capitulo-09.html#v12\" data-v=\"9.12\">9.12</a>). Retoma <a class=\"vref\" href=\"capitulo-07.html#v24\" data-v=\"7.24\">7.24</a>–<a class=\"vref\" href=\"capitulo-07.html#v25\" data-v=\"7.25\">7.25</a>, y prepara por contraste a los grandes seres de <a class=\"vref\" href=\"capitulo-09.html#v13\" data-v=\"9.13\">9.13</a>.</p>"}, {"id": "como-lo-adoran-los-grandes-seres", "desde": 13, "hasta": 15, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Cómo lo adoran los grandes seres: alabanza, esfuerzo, reverencia y conocimiento", "resumen": "<p>Los grandes seres, acogidos a la naturaleza divina, adoran a Kṛṣṇa con la mente puesta en nada más, sabiendo que es el origen de los seres (<a class=\"vref\" href=\"capitulo-09.html#v13\" data-v=\"9.13\">9.13</a>). La devoción tiene aquí gestos concretos: glorificarlo sin cesar, esforzarse, mantener firmes los votos, inclinarse ante él, permanecer siempre unido (<a class=\"vref\" href=\"capitulo-09.html#v14\" data-v=\"9.14\">9.14</a>). Otros lo veneran con el <a class=\"t\" href=\"glosario.html#jnana-yajna\" data-t=\"jnana-yajna\">sacrificio del conocimiento</a>, como uno, como distinto o de muchas maneras (<a class=\"vref\" href=\"capitulo-09.html#v15\" data-v=\"9.15\">9.15</a>). La devoción y el conocimiento aparecen así como dos formas de un mismo culto.</p>"}, {"id": "yo-soy-el-rito-y-el-mundo", "desde": 16, "hasta": 19, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Yo soy el rito, el padre y la madre, el ser y el no-ser", "resumen": "<p>Kṛṣṇa se identifica con cada elemento del sacrificio —el rito, la ofrenda, el mantra, la mantequilla, el fuego, la oblación (<a class=\"vref\" href=\"capitulo-09.html#v16\" data-v=\"9.16\">9.16</a>)—, con el origen del mundo —padre, madre, abuelo— y con la palabra sagrada que lo revela, la sílaba <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a> y los tres Vedas (<a class=\"vref\" href=\"capitulo-09.html#v17\" data-v=\"9.17\">9.17</a>). Es la meta y el refugio de quien se acerca a él, y el origen, la disolución y la semilla del mundo (<a class=\"vref\" href=\"capitulo-09.html#v18\" data-v=\"9.18\">9.18</a>); es el calor y la lluvia, la inmortalidad y la muerte, el ser y el no-ser (<a class=\"vref\" href=\"capitulo-09.html#v19\" data-v=\"9.19\">9.19</a>). Nada queda fuera: por eso puede ser adorado de muchas maneras (<a class=\"vref\" href=\"capitulo-09.html#v15\" data-v=\"9.15\">9.15</a>). La serie continúa la de <a class=\"vref\" href=\"capitulo-07.html#v8\" data-v=\"7.8\">7.8</a>–<a class=\"vref\" href=\"capitulo-07.html#v11\" data-v=\"7.11\">7.11</a> y anticipa el capítulo 10.</p>"}, {"id": "el-cielo-que-se-agota", "desde": 20, "hasta": 21, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El cielo que se agota: el ir y venir de los ritos", "resumen": "<p>Los que celebran los sacrificios del Veda para ganar el cielo lo alcanzan y gozan de él; pero, agotado el mérito, vuelven a nacer. El cielo es un fruto, y como todo fruto se acaba: el que busca deseos obtiene «el ir y venir» (<a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>; véase <a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a> y <a class=\"t\" href=\"glosario.html#devayana\" data-t=\"devayana\">devayāna</a>).</p>"}, {"id": "yo-me-hago-cargo", "desde": 22, "hasta": 22, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "«Yo me hago cargo»: lo que falta y lo que se tiene", "resumen": "<p>A quienes piensan sólo en él y lo adoran siempre, Kṛṣṇa les promete llevar su carga: procurarles lo que les falta y conservarles lo que tienen (<a class=\"t\" href=\"glosario.html#yoga-ksema\" data-t=\"yoga-ksema\">yoga-kṣema</a>). Es la respuesta a <a class=\"vref\" href=\"capitulo-02.html#v45\" data-v=\"2.45\">2.45</a>, que pedía vivir sin ese afán: quien se entrega por entero puede dejarlo, porque otro lo lleva.</p>"}, {"id": "todo-sacrificio-llega-a-el", "desde": 23, "hasta": 25, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Todo sacrificio llega a él", "resumen": "<p>Quien adora con fe a otra divinidad adora en realidad a Kṛṣṇa, aunque no según la regla, porque él es quien goza de todos los sacrificios y su señor; la falta está en no reconocerlo, y por eso se cae. Cada cual va a aquello a que se consagra: a los dioses, a los antepasados, a los espíritus, o a Kṛṣṇa (<a class=\"vref\" href=\"capitulo-09.html#v23\" data-v=\"9.23\">9.23</a>–<a class=\"vref\" href=\"capitulo-09.html#v25\" data-v=\"9.25\">9.25</a>; véase <a class=\"vref\" href=\"capitulo-07.html#v20\" data-v=\"7.20\">7.20</a>–<a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a>).</p>"}, {"id": "ofrecerlo-todo", "desde": 26, "hasta": 28, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Ofrecerlo todo: de la hoja y la flor a cada acto", "resumen": "<p>Kṛṣṇa no pide ofrendas costosas: una hoja, una flor, un fruto o agua, si se dan con <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>, le bastan (<a class=\"vref\" href=\"capitulo-09.html#v26\" data-v=\"9.26\">9.26</a>). La práctica se extiende luego a toda la vida: lo que se hace, se come, se sacrifica, se da o se sufre como austeridad, hacerlo como ofrenda a él (<a class=\"vref\" href=\"capitulo-09.html#v27\" data-v=\"9.27\">9.27</a>). Así se rompen las ataduras de la acción, también las de sus frutos buenos, y la renuncia se vuelve yoga (<a class=\"vref\" href=\"capitulo-09.html#v28\" data-v=\"9.28\">9.28</a>). Es la acción sin apego de los capítulos 3–5, dirigida ahora a Kṛṣṇa en persona.</p>"}, {"id": "mi-devoto-no-perece", "desde": 29, "hasta": 33, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El mismo para todos: ningún devoto se pierde", "resumen": "<p>Kṛṣṇa no odia ni prefiere a nadie, pero los que lo adoran están en él y él en ellos (<a class=\"vref\" href=\"capitulo-09.html#v29\" data-v=\"9.29\">9.29</a>). De ahí dos consecuencias. La devoción no exige un pasado intachable: el de peor conducta que lo adora sin reservas ha tomado la resolución recta y pronto se vuelve recto (<a class=\"vref\" href=\"capitulo-09.html#v30\" data-v=\"9.30\">9.30</a>–<a class=\"vref\" href=\"capitulo-09.html#v31\" data-v=\"9.31\">9.31</a>). Y no exige la condición que el Veda pedía: también los de origen pecaminoso, las mujeres, los vaiśyas y los śūdras alcanzan la meta suprema (<a class=\"vref\" href=\"capitulo-09.html#v32\" data-v=\"9.32\">9.32</a>); con más razón los brahmanes y los reyes sabios (<a class=\"vref\" href=\"capitulo-09.html#v33\" data-v=\"9.33\">9.33</a>).</p>"}, {"id": "ten-la-mente-en-mi", "desde": 34, "hasta": 34, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Ten la mente en mí: la devoción en cuatro gestos", "resumen": "<p>El capítulo termina con la práctica entera en una línea: tener la mente en Kṛṣṇa, ser su devoto, ofrecerle sacrificio e inclinarse ante él. Unido así y teniéndolo por meta, se llega a él. La fórmula volverá casi igual en <a class=\"vref\" href=\"capitulo-18.html#v65\" data-v=\"18.65\">18.65</a>.</p>"}]};
